fn env_truthy(name: &str) -> bool {
    std::env::var(name)
        .map(|value| matches!(value.trim(), "1" | "true" | "TRUE" | "yes" | "on"))
        .unwrap_or(false)
}
fn options_file_java_bool(
    _resource_manager: &crate::resources::manager::ClientResourceManager,
    key: &str,
    default: bool,
) -> bool {
    #[cfg(not(target_arch = "wasm32"))]
    let options_path = _resource_manager
        .assets_root()
        .parent()
        .and_then(|p| p.parent())
        .unwrap_or(&std::path::Path::new("."))
        .join("options.txt");
    #[cfg(target_arch = "wasm32")]
    let content = web_sys::window()
        .and_then(|w| w.local_storage().ok().flatten())
        .and_then(|s| s.get_item("options.txt").ok().flatten());
    #[cfg(not(target_arch = "wasm32"))]
    let content = std::fs::read_to_string(&options_path)
        .ok()
        .or_else(|| std::fs::read_to_string("options.txt").ok());
    let Some(content) = content else {
        return default;
    };
    content
        .lines()
        .find_map(|line| {
            let (raw_key, raw_val) = line.split_once(':')?;
            if raw_key.trim() == key {
                Some(raw_val.trim())
            } else {
                None
            }
        })
        .map(|value| matches!(value, "true" | "TRUE"))
        .unwrap_or(default)
}
