#[derive(Copy, Clone, Debug, Default, PartialEq, Eq)]
struct JavaTextureSamplerOptions {
    blur: bool,
    clamp: bool,
}
impl JavaTextureSamplerOptions {
    fn address_mode(self) -> wgpu::AddressMode {
        if self.clamp {
            wgpu::AddressMode::ClampToEdge
        } else {
            wgpu::AddressMode::Repeat
        }
    }
    fn min_mag_filter(self) -> wgpu::FilterMode {
        if self.blur {
            wgpu::FilterMode::Linear
        } else {
            wgpu::FilterMode::Nearest
        }
    }
}
fn resource_texture_sampler_options_like_java(
    metadata: Option<&[u8]>,
) -> Result<JavaTextureSamplerOptions, serde_json::Error> {
    #[derive(serde::Deserialize)]
    struct TextureMetadataSection {
        #[serde(default)]
        blur: bool,
        #[serde(default)]
        clamp: bool,
    }
    let Some(metadata) = metadata else {
        return Ok(JavaTextureSamplerOptions::default());
    };
    let document = serde_json::from_slice::<serde_json::Map<String, serde_json::Value>>(metadata)?;
    let Some(texture_section) = document.get("texture") else {
        return Ok(JavaTextureSamplerOptions::default());
    };
    let texture = serde_json::from_value::<TextureMetadataSection>(texture_section.clone())?;
    Ok(JavaTextureSamplerOptions {
        blur: texture.blur,
        clamp: texture.clamp,
    })
}
