fn block_outline_draw_ranges(
    index_count: u32,
    secondary_index_count: u32,
) -> (Option<std::ops::Range<u32>>, std::ops::Range<u32>) {
    let primary_start = secondary_index_count.min(index_count);
    let secondary = (primary_start > 0).then_some(0..primary_start);
    (secondary, primary_start..index_count)
}
#[allow(dead_code)]
fn append_aabb_outline_vertices(
    vertices: &mut Vec<LineVertex>,
    indices: &mut Vec<u32>,
    pos: BlockPos,
    local_box: AABB,
    color: [f32; 4],
    line_width: f32,
) {
    let local_x0 = local_box.min_x as f32;
    let local_y0 = local_box.min_y as f32;
    let local_z0 = local_box.min_z as f32;
    let local_x1 = local_box.max_x as f32;
    let local_y1 = local_box.max_y as f32;
    let local_z1 = local_box.max_z as f32;
    let x0 = pos.x as f32 + local_x0;
    let y0 = pos.y as f32 + local_y0;
    let z0 = pos.z as f32 + local_z0;
    let x1 = pos.x as f32 + local_x1;
    let y1 = pos.y as f32 + local_y1;
    let z1 = pos.z as f32 + local_z1;
    let corners = [
        [x0, y0, z0],
        [x1, y0, z0],
        [x1, y0, z1],
        [x0, y0, z1],
        [x0, y1, z0],
        [x1, y1, z0],
        [x1, y1, z1],
        [x0, y1, z1],
    ];
    const EDGES: [(usize, usize); 12] = [
        (0, 1),
        (1, 2),
        (2, 3),
        (3, 0),
        (4, 5),
        (5, 6),
        (6, 7),
        (7, 4),
        (0, 4),
        (1, 5),
        (2, 6),
        (3, 7),
    ];
    let local_corners = [
        [local_x0, local_y0, local_z0],
        [local_x1, local_y0, local_z0],
        [local_x1, local_y0, local_z1],
        [local_x0, local_y0, local_z1],
        [local_x0, local_y1, local_z0],
        [local_x1, local_y1, local_z0],
        [local_x1, local_y1, local_z1],
        [local_x0, local_y1, local_z1],
    ];
    for (a, b) in EDGES {
        let edge =
            glam::Vec3::from_array(local_corners[b]) - glam::Vec3::from_array(local_corners[a]);
        let normal = edge.normalize_or_zero().to_array();
        append_line_outline_quad(
            vertices, indices, corners[a], corners[b], color, normal, line_width,
        );
    }
}
fn append_line_outline_quad(
    vertices: &mut Vec<LineVertex>,
    indices: &mut Vec<u32>,
    first: [f32; 3],
    second: [f32; 3],
    color: [f32; 4],
    normal: [f32; 3],
    line_width: f32,
) {
    let base = u32::try_from(vertices.len()).expect("block outline vertex count exceeds u32");
    let packed_color = java_outline_color(color);
    let packed_normal = java_outline_normal(normal);
    let start = LineVertex {
        position: first,
        color: packed_color,
        normal: packed_normal,
        line_width,
    };
    let end = LineVertex {
        position: second,
        color: packed_color,
        normal: packed_normal,
        line_width,
    };
    vertices.extend([start, start, end, end]);
    indices.extend([base, base + 1, base + 2, base + 3, base + 2, base + 1]);
}
fn java_outline_color(color: [f32; 4]) -> [u8; 4] {
    color.map(|component| (component.clamp(0.0, 1.0) * 255.0) as u8)
}
fn java_outline_normal(normal: [f32; 3]) -> [i8; 4] {
    let pack = |component: f32| (component.clamp(-1.0, 1.0) * 127.0) as i8;
    [pack(normal[0]), pack(normal[1]), pack(normal[2]), 0]
}
#[allow(dead_code)]
fn append_shape_outline_vertices(
    vertices: &mut Vec<LineVertex>,
    indices: &mut Vec<u32>,
    pos: BlockPos,
    shape: &el_math::VoxelShape,
    color: [f32; 4],
    line_width: f32,
) {
    append_shape_outline_vertices_at_origin(
        vertices,
        indices,
        [pos.x as f32, pos.y as f32, pos.z as f32],
        shape,
        color,
        line_width,
    );
}
fn append_shape_outline_vertices_at_origin(
    vertices: &mut Vec<LineVertex>,
    indices: &mut Vec<u32>,
    origin: [f32; 3],
    shape: &el_math::VoxelShape,
    color: [f32; 4],
    line_width: f32,
) {
    shape.for_all_edges(|x1, y1, z1, x2, y2, z2| {
        let first = [
            origin[0] + x1 as f32,
            origin[1] + y1 as f32,
            origin[2] + z1 as f32,
        ];
        let second = [
            origin[0] + x2 as f32,
            origin[1] + y2 as f32,
            origin[2] + z2 as f32,
        ];
        let edge = glam::Vec3::new((x2 - x1) as f32, (y2 - y1) as f32, (z2 - z1) as f32);
        let normal = edge.normalize_or_zero().to_array();
        append_line_outline_quad(vertices, indices, first, second, color, normal, line_width);
    });
}
fn append_breaking_overlay_model(
    vertices: &mut Vec<Vertex>,
    indices: &mut Vec<u32>,
    model: &BakedModel,
    block_state: &BlockState,
    pos: BlockPos,
    model_origin: [f32; 3],
) {
    let seed = block_model_seed(block_state, pos);
    for quad in model.quads_for_seed(seed) {
        let start = vertices.len() as u32;
        let normal = direction_normal(quad.direction);
        let uvs = quad.vertex_positions.map(|local_pos| {
            let projected = sheeted_decal_position(local_pos, quad.direction);
            [-projected.x, -projected.y]
        });
        for (i, local_pos) in quad.vertex_positions.iter().enumerate() {
            let p = *local_pos + glam::Vec3::from_array(model_origin);
            vertices.push(Vertex {
                position: [p.x, p.y, p.z],
                tex_coords: uvs[i],
                normal: [normal.x, normal.y, normal.z],
                color: [1.0, 1.0, 1.0, 1.0],
                light: [1.0, 1.0],
            });
        }
        indices.extend_from_slice(&[start, start + 1, start + 2, start, start + 2, start + 3]);
    }
}
fn sheeted_decal_position(local_pos: glam::Vec3, direction: Direction) -> glam::Vec3 {
    let mut projected = glam::Quat::from_rotation_y(std::f32::consts::PI).mul_vec3(local_pos);
    projected = glam::Quat::from_rotation_x(-std::f32::consts::FRAC_PI_2).mul_vec3(projected);
    let direction_rotation = match direction {
        Direction::Down => glam::Quat::from_rotation_x(std::f32::consts::PI),
        Direction::Up => glam::Quat::IDENTITY,
        Direction::North => glam::Quat::from_euler(
            glam::EulerRot::XYZ,
            std::f32::consts::FRAC_PI_2,
            0.0,
            std::f32::consts::PI,
        ),
        Direction::South => glam::Quat::from_rotation_x(std::f32::consts::FRAC_PI_2),
        Direction::West => glam::Quat::from_euler(
            glam::EulerRot::XYZ,
            std::f32::consts::FRAC_PI_2,
            0.0,
            std::f32::consts::FRAC_PI_2,
        ),
        Direction::East => glam::Quat::from_euler(
            glam::EulerRot::XYZ,
            std::f32::consts::FRAC_PI_2,
            0.0,
            -std::f32::consts::FRAC_PI_2,
        ),
    };
    direction_rotation.mul_vec3(projected)
}
fn has_special_block_entity_renderer(path: &str) -> bool {
    path.ends_with("chest")
        || path.ends_with("shulker_box")
        || path == "conduit"
        || path == "decorated_pot"
        || path.ends_with("banner")
        || crate::render::block_entity::is_skull_block(path)
        || path.ends_with("copper_golem_statue")
        || path.ends_with("_sign")
}
fn has_tracked_client_block_entity(path: &str) -> bool {
    has_special_block_entity_renderer(path) || path == "moving_piston"
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RemoteBlockEventReceiver {
    ChestLid,
    ShulkerLid,
    DecoratedPotWobble,
    PistonBase,
    NoteBlock,
    Ignore,
}
fn remote_block_event_receiver_like_java(
    state: &BlockState,
    action_id: u8,
) -> RemoteBlockEventReceiver {
    if state.block.namespace != "minecraft" {
        return RemoteBlockEventReceiver::Ignore;
    }
    match state.block.path.as_str() {
        "piston" | "sticky_piston" if matches!(action_id, 0..=2) => {
            RemoteBlockEventReceiver::PistonBase
        }
        "decorated_pot" if action_id == 1 => RemoteBlockEventReceiver::DecoratedPotWobble,
        "note_block" => RemoteBlockEventReceiver::NoteBlock,
        path if path.ends_with("shulker_box") && action_id == 1 => {
            RemoteBlockEventReceiver::ShulkerLid
        }
        path if path.ends_with("chest") && action_id == 1 => RemoteBlockEventReceiver::ChestLid,
        _ => RemoteBlockEventReceiver::Ignore,
    }
}
fn is_vanilla_moving_piston(state: &BlockState) -> bool {
    state.block.namespace == "minecraft" && state.block.path == "moving_piston"
}
fn sign_texts_from_chunk(chunk: &Chunk) -> Vec<(BlockPos, ParsedSignText)> {
    chunk
        .block_entities
        .iter()
        .filter(|(_, data)| !data.nbt.is_empty())
        .filter_map(|(pos, data)| {
            let state = chunk.get_block_state(pos)?;
            crate::render::sign::is_sign_state(&state)
                .then(|| parse_sign_nbt(&data.nbt).map(|parsed| (*pos, parsed)))
                .flatten()
        })
        .collect()
}
fn moving_piston_entities_from_chunk(chunk: &Chunk) -> Vec<(BlockPos, MovingPistonBlockEntity)> {
    chunk
        .block_entities
        .iter()
        .filter_map(|(&pos, data)| {
            chunk
                .get_block_state(&pos)
                .filter(|state| is_vanilla_moving_piston(state))
                .and_then(|_| MovingPistonBlockEntity::from_block_entity_nbt(&data.nbt))
                .map(|entity| (pos, entity))
        })
        .collect()
}
fn requires_block_entity_mesh_rebuild(old_state: &BlockState, new_state: &BlockState) -> bool {
    old_state != new_state
        && (has_special_block_entity_renderer(&old_state.block.path)
            || has_special_block_entity_renderer(&new_state.block.path))
}
fn keeps_block_entity_for_copper_chest_transition(
    old_state: &BlockState,
    new_state: &BlockState,
) -> bool {
    const COPPER_CHEST_PATHS: &[&str] = &[
        "copper_chest",
        "exposed_copper_chest",
        "weathered_copper_chest",
        "oxidized_copper_chest",
        "waxed_copper_chest",
        "waxed_exposed_copper_chest",
        "waxed_weathered_copper_chest",
        "waxed_oxidized_copper_chest",
    ];
    old_state.block.namespace == "minecraft"
        && new_state.block.namespace == "minecraft"
        && COPPER_CHEST_PATHS.contains(&old_state.block.path.as_str())
        && COPPER_CHEST_PATHS.contains(&new_state.block.path.as_str())
}
fn replaces_special_block_entity_instance(old_state: &BlockState, new_state: &BlockState) -> bool {
    old_state.block != new_state.block
        && (has_special_block_entity_renderer(&old_state.block.path)
            || has_special_block_entity_renderer(&new_state.block.path))
        && !keeps_block_entity_for_copper_chest_transition(old_state, new_state)
}
pub(crate) fn sync_special_block_entity(
    chunk: &mut Chunk,
    pos: BlockPos,
    old_state: &BlockState,
    new_state: &BlockState,
) -> bool {
    if has_tracked_client_block_entity(&new_state.block.path) {
        let data = BlockEntityData {
            kind: new_state.block.to_string(),
            nbt: Vec::new(),
        };
        if old_state.block != new_state.block {
            if keeps_block_entity_for_copper_chest_transition(old_state, new_state) {
                if let Some(existing) = chunk.block_entities.get_mut(&pos) {
                    existing.kind = data.kind;
                    return true;
                }
            } else {
                chunk.block_entities.insert(pos, data);
                return true;
            }
        }
        if let std::collections::hash_map::Entry::Vacant(entry) = chunk.block_entities.entry(pos) {
            entry.insert(data);
            return true;
        }
    } else if old_state.block != new_state.block {
        return chunk.block_entities.remove(&pos).is_some();
    }
    false
}
fn mirror_block_state_into_remote_snapshot(
    remote_chunk_snapshots: &mut HashMap<ChunkPos, Arc<Chunk>>,
    pos: BlockPos,
    state: &BlockState,
) -> bool {
    let chunk_pos = ChunkPos::from_block(pos);
    let Some(snapshot) = remote_chunk_snapshots.get_mut(&chunk_pos) else {
        return false;
    };
    let snapshot = Arc::make_mut(snapshot);
    let Some(old_state) = snapshot.get_block_state(&pos) else {
        return false;
    };
    let state_changed = old_state != *state;
    if state_changed && !snapshot.set_block_state(&pos, state.clone()) {
        return false;
    }
    let block_entity_changed = sync_special_block_entity(snapshot, pos, &old_state, state);
    state_changed || block_entity_changed
}
