const JAVA_DIFFUSE_LIGHT_0: [f32; 4] = [0.161_690_2, 0.808_451_2, -0.565_915_8, 0.0];
const JAVA_DIFFUSE_LIGHT_1: [f32; 4] = [-0.161_690_2, 0.808_451_2, 0.565_915_8, 0.0];
const JAVA_NETHER_DIFFUSE_LIGHT_0: [f32; 4] = JAVA_DIFFUSE_LIGHT_0;
const JAVA_NETHER_DIFFUSE_LIGHT_1: [f32; 4] = [-0.161_690_2, -0.808_451_2, 0.565_915_8, 0.0];
const JAVA_CARDINAL_LIGHTING_DEFAULT: [f32; 4] = [0.5, 1.0, 0.8, 0.6];
const JAVA_CARDINAL_LIGHTING_NETHER: [f32; 4] = [0.9, 0.9, 0.8, 0.6];
fn brighten_fog_color(rgb: [f32; 3], brighten_factor: f32) -> [f32; 4] {
    let [red, green, blue] = rgb;
    if red == 0.0 || green == 0.0 || blue == 0.0 {
        return [red, green, blue, 1.0];
    }
    let max_color = red.max(green).max(blue);
    let target_scale = 1.0 / max_color.clamp(0.07, 1.0);
    let target_scale_max = 1.0 / max_color;
    let lerp = |from: f32, scale: f32| from + (from * scale - from) * brighten_factor;
    [
        lerp(
            red,
            if max_color != red {
                target_scale
            } else {
                target_scale_max
            },
        ),
        lerp(
            green,
            if max_color != green {
                target_scale
            } else {
                target_scale_max
            },
        ),
        lerp(
            blue,
            if max_color != blue {
                target_scale
            } else {
                target_scale_max
            },
        ),
        1.0,
    ]
}
