#[derive(Debug, Copy, Clone, bytemuck::Pod, bytemuck::Zeroable)]
struct NameTagVertex {
    position: [f32; 3],
    tex_coords: [f32; 2],
    color: [f32; 4],
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct NameTagTextureBatch {
    texture_index: usize,
    start_index: u32,
    index_count: u32,
}
#[derive(Default, Clone)]
struct NameTagTextLayer {
    vertices: Vec<NameTagVertex>,
    indices: Vec<u32>,
    batches: Vec<NameTagTextureBatch>,
    indices_by_texture: std::collections::BTreeMap<usize, Vec<u32>>,
}
impl NameTagTextLayer {
    fn append_quad(
        &mut self,
        texture_index: usize,
        top_left: glam::Vec3,
        bottom_left: glam::Vec3,
        bottom_right: glam::Vec3,
        top_right: glam::Vec3,
        uv: [[f32; 2]; 4],
        color: [f32; 4],
    ) {
        let base = self.vertices.len() as u32;
        self.vertices.extend([
            NameTagVertex {
                position: top_left.to_array(),
                tex_coords: uv[0],
                color,
            },
            NameTagVertex {
                position: bottom_left.to_array(),
                tex_coords: uv[1],
                color,
            },
            NameTagVertex {
                position: bottom_right.to_array(),
                tex_coords: uv[2],
                color,
            },
            NameTagVertex {
                position: top_right.to_array(),
                tex_coords: uv[3],
                color,
            },
        ]);
        self.indices_by_texture
            .entry(texture_index)
            .or_default()
            .extend([base, base + 1, base + 2, base, base + 2, base + 3]);
    }
    fn extend(&mut self, other: &NameTagTextLayer) {
        if other.vertices.is_empty() {
            return;
        }
        let base = self.vertices.len() as u32;
        self.vertices.extend_from_slice(&other.vertices);
        for (&texture_index, indices) in &other.indices_by_texture {
            let target = self.indices_by_texture.entry(texture_index).or_default();
            target.reserve(indices.len());
            for &index in indices {
                target.push(base + index);
            }
        }
    }
    fn rebuild_indices_and_batches(&mut self) {
        self.indices.clear();
        self.batches.clear();
        for (&texture_index, indices) in &self.indices_by_texture {
            if indices.is_empty() {
                continue;
            }
            let start_index = self.indices.len() as u32;
            let index_count = indices.len() as u32;
            self.indices.extend_from_slice(indices);
            self.batches.push(NameTagTextureBatch {
                texture_index,
                start_index,
                index_count,
            });
        }
    }
}
#[derive(Default, Clone)]
struct NameTagFlatLayer {
    vertices: Vec<NameTagVertex>,
    indices: Vec<u32>,
}
impl NameTagFlatLayer {
    fn extend(&mut self, other: &NameTagFlatLayer) {
        if other.vertices.is_empty() || other.indices.is_empty() {
            return;
        }
        let base = self.vertices.len() as u32;
        self.vertices.extend_from_slice(&other.vertices);
        self.indices.reserve(other.indices.len());
        for &index in &other.indices {
            self.indices.push(base + index);
        }
    }
}
#[derive(Default, Clone)]
struct NameTagSeeThroughSubmit {
    distance_to_camera_sq: f32,
    text: NameTagTextLayer,
    background: NameTagFlatLayer,
    effects: NameTagFlatLayer,
}
#[derive(Default)]
struct NameTagMesh {
    normal_text: NameTagTextLayer,
    normal_background: NameTagFlatLayer,
    normal_effects: NameTagFlatLayer,
    see_through_text: NameTagTextLayer,
    see_through_background: NameTagFlatLayer,
    see_through_effects: NameTagFlatLayer,
    see_through_submits: Vec<NameTagSeeThroughSubmit>,
}
impl NameTagMesh {
    fn append_quad(
        vertices: &mut Vec<NameTagVertex>,
        indices: &mut Vec<u32>,
        top_left: glam::Vec3,
        bottom_left: glam::Vec3,
        bottom_right: glam::Vec3,
        top_right: glam::Vec3,
        uv: [[f32; 2]; 4],
        color: [f32; 4],
    ) -> u32 {
        let base = vertices.len() as u32;
        vertices.extend([
            NameTagVertex {
                position: top_left.to_array(),
                tex_coords: uv[0],
                color,
            },
            NameTagVertex {
                position: bottom_left.to_array(),
                tex_coords: uv[1],
                color,
            },
            NameTagVertex {
                position: bottom_right.to_array(),
                tex_coords: uv[2],
                color,
            },
            NameTagVertex {
                position: top_right.to_array(),
                tex_coords: uv[3],
                color,
            },
        ]);
        indices.extend([base, base + 1, base + 2, base, base + 2, base + 3]);
        base
    }
    #[allow(dead_code)]
    fn append_text_quad(
        &mut self,
        texture_index: usize,
        top_left: glam::Vec3,
        bottom_left: glam::Vec3,
        bottom_right: glam::Vec3,
        top_right: glam::Vec3,
        uv: [[f32; 2]; 4],
        color: [f32; 4],
    ) {
        self.normal_text.append_quad(
            texture_index,
            top_left,
            bottom_left,
            bottom_right,
            top_right,
            uv,
            color,
        );
        self.normal_text.rebuild_indices_and_batches();
    }
    fn finish(&mut self) {
        for submit in &self.see_through_submits {
            self.see_through_background.extend(&submit.background);
            self.see_through_text.extend(&submit.text);
            self.see_through_effects.extend(&submit.effects);
        }
        self.see_through_text.rebuild_indices_and_batches();
        self.normal_text.rebuild_indices_and_batches();
    }
}
const NAME_TAG_SCALE: f32 = 0.025;
const NAME_TAG_SCORE_LIFT: f32 = 9.0 * 1.15 * NAME_TAG_SCALE;
const NAME_TAG_FONT_BASELINE: f32 = 7.0;
const NAME_TAG_SEE_THROUGH_ALPHA: f32 = 128.0 / 255.0;
const NAME_TAG_GLYPH_BOLD_OFFSET: f32 = 1.0;
const NAME_TAG_EFFECT_DEPTH: f32 = 0.01;
const NAME_TAG_BOLD_Z_FIGHTER: f32 = 0.001;
const NAME_TAG_NORMAL_DEPTH_WRITE: bool = true;
fn world_name_tag_glyph_advance(advance: f32, bold: bool) -> f32 {
    advance + bold.then_some(NAME_TAG_GLYPH_BOLD_OFFSET).unwrap_or(0.0)
}
fn world_name_tag_obfuscated_char(
    font: &crate::ui::gui::font::FontRenderer,
    source: char,
    seed: u64,
    glyph_index: usize,
) -> char {
    if source == ' ' {
        return source;
    }
    let target_width = font.glyph(source).advance.ceil() as i32;
    let Some(candidates) = font.candidates_by_width(target_width) else {
        return source;
    };
    if candidates.is_empty() {
        return source;
    }
    let mut mixed = seed ^ (glyph_index as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);
    mixed ^= source as u64;
    mixed ^= mixed >> 30;
    mixed = mixed.wrapping_mul(0xBF58_476D_1CE4_E5B9);
    mixed ^= mixed >> 27;
    mixed = mixed.wrapping_mul(0x94D0_49BB_1331_11EB);
    mixed ^= mixed >> 31;
    candidates[mixed as usize % candidates.len()]
}
fn name_tag_color(rgb: u32, alpha: f32) -> [f32; 4] {
    [
        ((rgb >> 16) & 0xFF) as f32 / 255.0,
        ((rgb >> 8) & 0xFF) as f32 / 255.0,
        (rgb & 0xFF) as f32 / 255.0,
        alpha,
    ]
}
fn append_name_tag_flat_quad(
    layer: &mut NameTagFlatLayer,
    top_left: glam::Vec3,
    bottom_left: glam::Vec3,
    bottom_right: glam::Vec3,
    top_right: glam::Vec3,
    color: [f32; 4],
) {
    NameTagMesh::append_quad(
        &mut layer.vertices,
        &mut layer.indices,
        top_left,
        bottom_left,
        bottom_right,
        top_right,
        [[0.0, 0.0], [0.0, 1.0], [1.0, 1.0], [1.0, 0.0]],
        color,
    );
}
struct CachedNameTagGlyph {
    style: crate::ui::chat::chat_component::WorldTextGlyph,
    metrics: crate::ui::gui::font::Glyph,
    advance: f32,
}
struct CachedNameTagLine {
    glyphs: Vec<CachedNameTagGlyph>,
    has_obfuscated: bool,
}
struct CachedNameTagLayout {
    lines: Vec<CachedNameTagLine>,
}
struct CachedSignTextMesh {
    state: BlockState,
    parsed: ParsedSignText,
    layer: NameTagTextLayer,
}
const NAME_TAG_CACHE_MAX_ENTRIES: usize = 8192;
fn name_tag_layout(font: &crate::ui::gui::font::FontRenderer, text: &str) -> CachedNameTagLayout {
    let source_glyphs = crate::ui::chat::chat_component::ansi_world_glyphs(text);
    let lines = [source_glyphs];
    let mut cached_lines = Vec::with_capacity(lines.len());
    for line_source_glyphs in lines {
        let mut glyphs = Vec::with_capacity(line_source_glyphs.len());
        let mut has_obfuscated = false;
        for style in line_source_glyphs {
            if style.obfuscated {
                has_obfuscated = true;
                glyphs.push(CachedNameTagGlyph {
                    style,
                    metrics: crate::ui::gui::font::Glyph {
                        texture_index: 0,
                        u0: 0.0,
                        v0: 0.0,
                        u1: 0.0,
                        v1: 0.0,
                        left: 0.0,
                        width: 0.0,
                        height: 0.0,
                        ascent: 0.0,
                        advance: 0.0,
                    },
                    advance: 0.0,
                });
                continue;
            }
            let glyph = font.glyph(style.ch);
            glyphs.push(CachedNameTagGlyph {
                advance: world_name_tag_glyph_advance(glyph.advance, style.bold),
                metrics: crate::ui::gui::font::Glyph {
                    texture_index: glyph.texture_index,
                    u0: glyph.u0,
                    v0: glyph.v0,
                    u1: glyph.u1,
                    v1: glyph.v1,
                    left: glyph.left,
                    width: glyph.width,
                    height: glyph.height,
                    ascent: glyph.ascent,
                    advance: glyph.advance,
                },
                style,
            });
        }
        cached_lines.push(CachedNameTagLine {
            glyphs,
            has_obfuscated,
        });
    }
    CachedNameTagLayout {
        lines: cached_lines,
    }
}
fn build_sign_text_layer(
    font: &crate::ui::gui::font::FontRenderer,
    state: &BlockState,
    parsed: &ParsedSignText,
    pos: BlockPos,
) -> NameTagTextLayer {
    let mut layer = NameTagTextLayer::default();
    let advance_of =
        |ch: char, bold: bool| world_name_tag_glyph_advance(font.glyph(ch).advance, bold);
    let (mut front_rows, mut back_rows) = crate::render::sign::sign_row_layout(parsed, advance_of);
    for (front, matrix) in [
        (true, crate::render::sign::sign_face_matrix(state, true)),
        (false, crate::render::sign::sign_face_matrix(state, false)),
    ] {
        let rows = if front {
            std::mem::take(&mut front_rows)
        } else {
            std::mem::take(&mut back_rows)
        };
        for row in rows {
            let width: f32 = row.glyphs.iter().map(|g| g.advance).sum();
            let mut x = -width * 0.5;
            let origin = glam::Vec3::new(pos.x as f32, pos.y as f32, pos.z as f32);
            let emit =
                |layer: &mut NameTagTextLayer, glyph_char: char, gx: f32, gy: f32, rgb: u32| {
                    let glyph = font.glyph(glyph_char);
                    if glyph.width <= 0.0 || glyph.height <= 0.0 {
                        return;
                    }
                    let left = gx + glyph.left;
                    let right = left + glyph.width;
                    let glyph_up = NAME_TAG_FONT_BASELINE - glyph.ascent;
                    let top = gy + glyph_up;
                    let bottom = top + glyph.height;
                    let local_top = matrix.transform_point3(glam::Vec3::new(left, top, 0.0));
                    let local_bottom = matrix.transform_point3(glam::Vec3::new(left, bottom, 0.0));
                    let local_right_bottom =
                        matrix.transform_point3(glam::Vec3::new(right, bottom, 0.0));
                    let local_right_top = matrix.transform_point3(glam::Vec3::new(right, top, 0.0));
                    layer.append_quad(
                        glyph.texture_index,
                        origin + local_top,
                        origin + local_bottom,
                        origin + local_right_bottom,
                        origin + local_right_top,
                        [
                            [glyph.u0, glyph.v0],
                            [glyph.u0, glyph.v1],
                            [glyph.u1, glyph.v1],
                            [glyph.u1, glyph.v0],
                        ],
                        name_tag_color(rgb, 1.0),
                    );
                };
            for row_glyph in &row.glyphs {
                let rgb = row_glyph.rgb_override.unwrap_or(row.tint_rgb);
                emit(&mut layer, row_glyph.glyph.ch, x, row.y, rgb);
                if row_glyph.glyph.bold {
                    emit(
                        &mut layer,
                        row_glyph.glyph.ch,
                        x + NAME_TAG_GLYPH_BOLD_OFFSET,
                        row.y,
                        rgb,
                    );
                }
                x += row_glyph.advance;
            }
        }
    }
    layer
}
fn append_world_name_tag_from_layout(
    mesh: &mut NameTagMesh,
    font: &crate::ui::gui::font::FontRenderer,
    layout: &CachedNameTagLayout,
    anchor: glam::Vec3,
    camera_right: glam::Vec3,
    camera_up: glam::Vec3,
    camera_forward: glam::Vec3,
    font_offset: f32,
    text_alpha: f32,
    background_alpha: f32,
    see_through: bool,
    distance_to_camera_sq: f32,
    obfuscation_seed: u64,
) {
    let mut see_through_submit = see_through.then(|| NameTagSeeThroughSubmit {
        distance_to_camera_sq,
        ..NameTagSeeThroughSubmit::default()
    });
    let to_world = |x: f32, y: f32, z: f32| {
        anchor + camera_right * (x * NAME_TAG_SCALE) + camera_up * (-y * NAME_TAG_SCALE)
            - camera_forward * (z * NAME_TAG_SCALE)
    };
    let normal_text_alpha = text_alpha
        * if see_through {
            1.0
        } else {
            NAME_TAG_SEE_THROUGH_ALPHA
        };
    for (line_idx, line) in layout.lines.iter().enumerate() {
        let line_y = font_offset + line_idx as f32 * 10.0;
        let total_advance = if line.has_obfuscated {
            line.glyphs
                .iter()
                .enumerate()
                .map(|(index, cached)| {
                    if cached.style.obfuscated {
                        let ch = world_name_tag_obfuscated_char(
                            font,
                            cached.style.ch,
                            obfuscation_seed ^ ((line_idx as u64) << 32),
                            index,
                        );
                        world_name_tag_glyph_advance(font.glyph(ch).advance, cached.style.bold)
                    } else {
                        cached.advance
                    }
                })
                .sum::<f32>()
        } else {
            line.glyphs.iter().map(|cached| cached.advance).sum::<f32>()
        };
        let width = total_advance.ceil();
        let mut x = -width * 0.5;
        if background_alpha > 0.0 && (!line.glyphs.is_empty() || line_idx == 0) {
            let left = -width * 0.5 - 1.0;
            let right = x + total_advance;
            let top = line_y - 1.0;
            let bottom = line_y + 9.0;
            let p0 = to_world(left, top, -NAME_TAG_EFFECT_DEPTH);
            let p1 = to_world(left, bottom, -NAME_TAG_EFFECT_DEPTH);
            let p2 = to_world(right, bottom, -NAME_TAG_EFFECT_DEPTH);
            let p3 = to_world(right, top, -NAME_TAG_EFFECT_DEPTH);
            if see_through {
                append_name_tag_flat_quad(
                    &mut see_through_submit
                        .as_mut()
                        .expect("see-through name tag has its own submit")
                        .background,
                    p0,
                    p1,
                    p2,
                    p3,
                    [0.0, 0.0, 0.0, background_alpha],
                );
            } else {
                append_name_tag_flat_quad(
                    &mut mesh.normal_background,
                    p0,
                    p1,
                    p2,
                    p3,
                    [0.0, 0.0, 0.0, background_alpha],
                );
            }
        }
        for (glyph_index, cached) in line.glyphs.iter().enumerate() {
            let style = &cached.style;
            let glyph = if style.obfuscated {
                let ch = world_name_tag_obfuscated_char(
                    font,
                    style.ch,
                    obfuscation_seed ^ ((line_idx as u64) << 32),
                    glyph_index,
                );
                font.glyph(ch)
            } else {
                &cached.metrics
            };
            let advance = if style.obfuscated {
                world_name_tag_glyph_advance(glyph.advance, style.bold)
            } else {
                cached.advance
            };
            let text_color = name_tag_color(style.color, normal_text_alpha);
            if glyph.width > 0.0 && glyph.height > 0.0 {
                let append_glyph = |layer: &mut NameTagTextLayer, glyph_x: f32, z: f32, color| {
                    let left = glyph_x + glyph.left;
                    let right = left + glyph.width;
                    let glyph_up = NAME_TAG_FONT_BASELINE - glyph.ascent;
                    let glyph_down = glyph_up + glyph.height;
                    let top = line_y + glyph_up;
                    let bottom = top + glyph.height;
                    let italic_top_shear = if style.italic {
                        1.0 - 0.25 * glyph_up
                    } else {
                        0.0
                    };
                    let italic_bottom_shear = if style.italic {
                        1.0 - 0.25 * glyph_down
                    } else {
                        0.0
                    };
                    let thickness = if style.bold { 0.1 } else { 0.0 };
                    layer.append_quad(
                        glyph.texture_index,
                        to_world(left + italic_top_shear - thickness, top - thickness, z),
                        to_world(
                            left + italic_bottom_shear - thickness,
                            bottom + thickness,
                            z,
                        ),
                        to_world(
                            right + italic_bottom_shear + thickness,
                            bottom + thickness,
                            z,
                        ),
                        to_world(right + italic_top_shear + thickness, top - thickness, z),
                        [
                            [glyph.u0, glyph.v0],
                            [glyph.u0, glyph.v1],
                            [glyph.u1, glyph.v1],
                            [glyph.u1, glyph.v0],
                        ],
                        color,
                    );
                };
                append_glyph(&mut mesh.normal_text, x, 0.0, text_color);
                if style.bold {
                    append_glyph(
                        &mut mesh.normal_text,
                        x + NAME_TAG_GLYPH_BOLD_OFFSET,
                        NAME_TAG_BOLD_Z_FIGHTER,
                        text_color,
                    );
                }
                if see_through {
                    let see_through_color =
                        name_tag_color(style.color, text_alpha * NAME_TAG_SEE_THROUGH_ALPHA);
                    append_glyph(
                        &mut see_through_submit
                            .as_mut()
                            .expect("see-through name tag has its own submit")
                            .text,
                        x,
                        0.0,
                        see_through_color,
                    );
                    if style.bold {
                        append_glyph(
                            &mut see_through_submit
                                .as_mut()
                                .expect("see-through name tag has its own submit")
                                .text,
                            x + NAME_TAG_GLYPH_BOLD_OFFSET,
                            NAME_TAG_BOLD_Z_FIGHTER,
                            see_through_color,
                        );
                    }
                }
            }
            let effect_left = if glyph_index == 0 { x - 1.0 } else { x };
            let append_effect = |layer: &mut NameTagFlatLayer, top: f32, bottom: f32, color| {
                append_name_tag_flat_quad(
                    layer,
                    to_world(effect_left, top, NAME_TAG_EFFECT_DEPTH),
                    to_world(effect_left, bottom, NAME_TAG_EFFECT_DEPTH),
                    to_world(x + advance, bottom, NAME_TAG_EFFECT_DEPTH),
                    to_world(x + advance, top, NAME_TAG_EFFECT_DEPTH),
                    color,
                );
            };
            if style.strikethrough {
                append_effect(
                    &mut mesh.normal_effects,
                    line_y + 3.5,
                    line_y + 4.5,
                    text_color,
                );
                if see_through {
                    append_effect(
                        &mut see_through_submit
                            .as_mut()
                            .expect("see-through name tag has its own submit")
                            .effects,
                        line_y + 3.5,
                        line_y + 4.5,
                        name_tag_color(style.color, text_alpha * NAME_TAG_SEE_THROUGH_ALPHA),
                    );
                }
            }
            if style.underlined {
                append_effect(
                    &mut mesh.normal_effects,
                    line_y + 8.0,
                    line_y + 9.0,
                    text_color,
                );
                if see_through {
                    append_effect(
                        &mut see_through_submit
                            .as_mut()
                            .expect("see-through name tag has its own submit")
                            .effects,
                        line_y + 8.0,
                        line_y + 9.0,
                        name_tag_color(style.color, text_alpha * NAME_TAG_SEE_THROUGH_ALPHA),
                    );
                }
            }
            x += advance;
        }
    }
    if let Some(mut submit) = see_through_submit {
        submit.text.rebuild_indices_and_batches();
        mesh.see_through_submits.push(submit);
    }
}
fn append_world_text_display(
    mesh: &mut NameTagMesh,
    font: &crate::ui::gui::font::FontRenderer,
    entity: &RemoteEntityRenderState,
    state: &crate::render::entity::display::TextDisplayState,
    camera_pos: glam::Vec3,
    camera_yaw_deg: f32,
    camera_pitch_deg: f32,
    partial_tick: f32,
    obfuscation_seed: u64,
) {
    if state.text.is_empty() {
        return;
    }
    let entity_pos = entity.render_position(partial_tick);
    let distance_to_camera_sq = entity_pos.distance_squared(camera_pos);
    let max_dist = state.view_range * 64.0;
    if distance_to_camera_sq > max_dist * max_dist {
        return;
    }
    let (lines, max_line_width) = crate::render::entity::display::split_text_display_lines(
        font,
        &state.text,
        state.line_width,
    );
    if lines.is_empty() {
        return;
    }
    let line_count = lines.len();
    let total_height = (line_count * 10).saturating_sub(1) as f32;
    let entity_yaw_deg = entity.java_y_rot_degrees;
    let entity_pitch_deg = entity.pitch.to_degrees();
    let model_matrix = crate::render::entity::display::compute_text_display_matrix(
        entity_pos,
        entity_yaw_deg,
        entity_pitch_deg,
        camera_yaw_deg,
        camera_pitch_deg,
        state,
        max_line_width,
        total_height,
    );
    let to_world = |x: f32, y: f32, z: f32| model_matrix.transform_point3(glam::Vec3::new(x, y, z));
    let flags = state.flags;
    let has_shadow = (flags & 1) != 0;
    let see_through = (flags & 2) != 0;
    let use_default_bg = (flags & 4) != 0;
    let alignment = crate::render::entity::display::TextDisplayAlignment::from_flags(flags);
    let text_opacity = if state.text_opacity == -1 {
        1.0
    } else {
        (state.text_opacity as u8 as f32) / 255.0
    };
    let bg_color = if use_default_bg {
        [0.0, 0.0, 0.0, 0.25]
    } else {
        crate::render::entity::display::unpack_argb_color(state.background_color, None)
    };
    let mut see_through_submit = see_through.then(|| NameTagSeeThroughSubmit {
        distance_to_camera_sq,
        ..NameTagSeeThroughSubmit::default()
    });
    if bg_color[3] > 0.0 {
        let p0 = to_world(-1.0, -1.0, -0.01);
        let p1 = to_world(-1.0, total_height, -0.01);
        let p2 = to_world(max_line_width, total_height, -0.01);
        let p3 = to_world(max_line_width, -1.0, -0.01);
        if let Some(submit) = see_through_submit.as_mut() {
            append_name_tag_flat_quad(&mut submit.background, p0, p1, p2, p3, bg_color);
        } else {
            append_name_tag_flat_quad(&mut mesh.normal_background, p0, p1, p2, p3, bg_color);
        }
    }
    for (line_idx, line) in lines.iter().enumerate() {
        let line_y = line_idx as f32 * 10.0;
        let line_offset = match alignment {
            crate::render::entity::display::TextDisplayAlignment::Left => 0.0,
            crate::render::entity::display::TextDisplayAlignment::Right => {
                max_line_width - line.width
            }
            crate::render::entity::display::TextDisplayAlignment::Center => {
                (max_line_width - line.width) * 0.5
            }
        };
        let mut x = line_offset;
        for (glyph_index, glyph_info) in line.glyphs.iter().enumerate() {
            let ch = if glyph_info.obfuscated {
                world_name_tag_obfuscated_char(
                    font,
                    glyph_info.ch,
                    obfuscation_seed ^ ((line_idx as u64) << 32),
                    glyph_index,
                )
            } else {
                glyph_info.ch
            };
            let glyph = font.glyph(ch);
            let advance = world_name_tag_glyph_advance(glyph.advance, glyph_info.bold);
            let text_color = name_tag_color(glyph_info.color, text_opacity);
            let shadow_color = [
                text_color[0] * 0.25,
                text_color[1] * 0.25,
                text_color[2] * 0.25,
                text_opacity,
            ];
            if glyph.width > 0.0 && glyph.height > 0.0 {
                let left = x + glyph.left;
                let right = left + glyph.width;
                let glyph_up = NAME_TAG_FONT_BASELINE - glyph.ascent;
                let glyph_down = glyph_up + glyph.height;
                let top = line_y + glyph_up;
                let bottom = top + glyph.height;
                let italic_top_shear = if glyph_info.italic {
                    1.0 - 0.25 * glyph_up
                } else {
                    0.0
                };
                let italic_bottom_shear = if glyph_info.italic {
                    1.0 - 0.25 * glyph_down
                } else {
                    0.0
                };
                let thickness = if glyph_info.bold { 0.1 } else { 0.0 };
                let append_glyph = |layer: &mut NameTagTextLayer,
                                    glyph_x_offset: f32,
                                    glyph_y_offset: f32,
                                    z: f32,
                                    color| {
                    layer.append_quad(
                        glyph.texture_index,
                        to_world(
                            left + glyph_x_offset + italic_top_shear - thickness,
                            top + glyph_y_offset - thickness,
                            z,
                        ),
                        to_world(
                            left + glyph_x_offset + italic_bottom_shear - thickness,
                            bottom + glyph_y_offset + thickness,
                            z,
                        ),
                        to_world(
                            right + glyph_x_offset + italic_bottom_shear + thickness,
                            bottom + glyph_y_offset + thickness,
                            z,
                        ),
                        to_world(
                            right + glyph_x_offset + italic_top_shear + thickness,
                            top + glyph_y_offset - thickness,
                            z,
                        ),
                        [
                            [glyph.u0, glyph.v0],
                            [glyph.u0, glyph.v1],
                            [glyph.u1, glyph.v1],
                            [glyph.u1, glyph.v0],
                        ],
                        color,
                    );
                };
                let text_z = if has_shadow { 0.03 } else { 0.0 };
                if has_shadow {
                    if let Some(submit) = see_through_submit.as_mut() {
                        append_glyph(&mut submit.text, 1.0, 1.0, 0.0, shadow_color);
                        if glyph_info.bold {
                            append_glyph(
                                &mut submit.text,
                                1.0 + NAME_TAG_GLYPH_BOLD_OFFSET,
                                1.0,
                                NAME_TAG_BOLD_Z_FIGHTER,
                                shadow_color,
                            );
                        }
                    } else {
                        append_glyph(&mut mesh.normal_text, 1.0, 1.0, 0.0, shadow_color);
                        if glyph_info.bold {
                            append_glyph(
                                &mut mesh.normal_text,
                                1.0 + NAME_TAG_GLYPH_BOLD_OFFSET,
                                1.0,
                                NAME_TAG_BOLD_Z_FIGHTER,
                                shadow_color,
                            );
                        }
                    }
                }
                if let Some(submit) = see_through_submit.as_mut() {
                    append_glyph(&mut submit.text, 0.0, 0.0, text_z, text_color);
                    if glyph_info.bold {
                        append_glyph(
                            &mut submit.text,
                            NAME_TAG_GLYPH_BOLD_OFFSET,
                            0.0,
                            text_z + NAME_TAG_BOLD_Z_FIGHTER,
                            text_color,
                        );
                    }
                } else {
                    append_glyph(&mut mesh.normal_text, 0.0, 0.0, text_z, text_color);
                    if glyph_info.bold {
                        append_glyph(
                            &mut mesh.normal_text,
                            NAME_TAG_GLYPH_BOLD_OFFSET,
                            0.0,
                            text_z + NAME_TAG_BOLD_Z_FIGHTER,
                            text_color,
                        );
                    }
                }
            }
            let text_z = if has_shadow { 0.03 } else { 0.0 };
            let effect_z = text_z + NAME_TAG_EFFECT_DEPTH;
            let effect_left = if glyph_index == 0 { x - 1.0 } else { x };
            let append_effect = |layer: &mut NameTagFlatLayer, top: f32, bottom: f32, color| {
                append_name_tag_flat_quad(
                    layer,
                    to_world(effect_left, top, effect_z),
                    to_world(effect_left, bottom, effect_z),
                    to_world(x + advance, bottom, effect_z),
                    to_world(x + advance, top, effect_z),
                    color,
                );
            };
            if glyph_info.strikethrough {
                if let Some(submit) = see_through_submit.as_mut() {
                    append_effect(&mut submit.effects, line_y + 3.5, line_y + 4.5, text_color);
                } else {
                    append_effect(
                        &mut mesh.normal_effects,
                        line_y + 3.5,
                        line_y + 4.5,
                        text_color,
                    );
                }
            }
            if glyph_info.underlined {
                if let Some(submit) = see_through_submit.as_mut() {
                    append_effect(&mut submit.effects, line_y + 8.0, line_y + 9.0, text_color);
                } else {
                    append_effect(
                        &mut mesh.normal_effects,
                        line_y + 8.0,
                        line_y + 9.0,
                        text_color,
                    );
                }
            }
            x += advance;
        }
    }
    if let Some(mut submit) = see_through_submit {
        submit.text.rebuild_indices_and_batches();
        mesh.see_through_submits.push(submit);
    }
}
impl CameraUniform {
    fn new() -> Self {
        Self {
            view_proj: glam::Mat4::IDENTITY.to_cols_array_2d(),
            lightmap_factors: [1.0, 1.4, -1.0, -1.0],
            screen_size: [1.0, 1.0, 0.0, 0.0],
            lightmap_effects: [0.0, 0.0, 0.0, 0.5],
            lightmap_block_light_tint: [1.0, 216.0 / 255.0, 140.0 / 255.0, 0.0],
            lightmap_sky_light_color: [1.0, 1.0, 1.0, 0.0],
            lightmap_ambient_color: [10.0 / 255.0, 10.0 / 255.0, 10.0 / 255.0, 0.0],
            lightmap_night_vision_color: [153.0 / 255.0, 153.0 / 255.0, 153.0 / 255.0, 0.0],
            diffuse_light_0: JAVA_DIFFUSE_LIGHT_0,
            diffuse_light_1: JAVA_DIFFUSE_LIGHT_1,
            cardinal_lighting: JAVA_CARDINAL_LIGHTING_DEFAULT,
            fog_color: [0.0, 0.0, 0.0, 0.0],
            fog_distances: [f32::MAX, f32::MAX, f32::MAX, f32::MAX],
            fog_camera_position: [0.0, 0.0, 0.0, 0.0],
            overlay_color: [1.0, 1.0, 1.0, 1.0],
        }
    }
    fn update_fog(
        &mut self,
        camera_position: glam::Vec3,
        color: [f32; 4],
        environmental: (f32, f32),
        render_distance: (f32, f32),
        nether_lighting: bool,
    ) {
        self.fog_camera_position = [camera_position.x, camera_position.y, camera_position.z, 0.0];
        self.fog_color = color;
        self.fog_distances = [
            environmental.0,
            environmental.1,
            render_distance.0,
            render_distance.1,
        ];
        if nether_lighting {
            self.diffuse_light_0 = JAVA_NETHER_DIFFUSE_LIGHT_0;
            self.diffuse_light_1 = JAVA_NETHER_DIFFUSE_LIGHT_1;
            self.cardinal_lighting = JAVA_CARDINAL_LIGHTING_NETHER;
        } else {
            self.diffuse_light_0 = JAVA_DIFFUSE_LIGHT_0;
            self.diffuse_light_1 = JAVA_DIFFUSE_LIGHT_1;
            self.cardinal_lighting = JAVA_CARDINAL_LIGHTING_DEFAULT;
        }
    }
    fn update_view_proj(&mut self, camera: &Camera, aspect: f32) {
        self.view_proj = camera
            .build_view_projection_matrix(aspect)
            .to_cols_array_2d();
    }
    fn update_outline_view_proj(&mut self, camera: &Camera, aspect: f32) {
        self.view_proj = camera
            .build_outline_view_projection_matrix(aspect)
            .to_cols_array_2d();
    }
    fn update_translation_free_view_proj(&mut self, camera: &Camera, aspect: f32) {
        self.view_proj = camera
            .render_view_rotation_projection_matrix(aspect)
            .to_cols_array_2d();
    }
}
