#[derive(Clone, Copy)]
struct TranslucentQuad {
    center: glam::Vec3,
    indices: [u32; 6],
}
fn translucent_quads(vertices: &[Vertex], indices: &[u32]) -> Vec<TranslucentQuad> {
    indices
        .chunks_exact(6)
        .filter_map(|indices| {
            let mut center = glam::Vec3::ZERO;
            let mut unique = [u32::MAX; 4];
            let mut unique_len = 0usize;
            for &index in indices {
                if unique[..unique_len].contains(&index) {
                    continue;
                }
                if unique_len == unique.len() {
                    return None;
                }
                unique[unique_len] = index;
                unique_len += 1;
                center += glam::Vec3::from_array(vertices.get(index as usize)?.position);
            }
            if unique_len != 4 {
                return None;
            }
            center /= unique_len as f32;
            Some(TranslucentQuad {
                center,
                indices: indices.try_into().ok()?,
            })
        })
        .collect()
}
fn sorted_translucent_indices(quads: &[TranslucentQuad], camera: glam::Vec3) -> Vec<u32> {
    let mut order = (0..quads.len()).collect::<Vec<_>>();
    order.sort_by(|&left, &right| {
        let left_distance = quads[left].center.distance_squared(camera);
        let right_distance = quads[right].center.distance_squared(camera);
        right_distance.total_cmp(&left_distance)
    });
    let mut result = Vec::with_capacity(quads.len() * 6);
    for quad_index in order {
        result.extend_from_slice(&quads[quad_index].indices);
    }
    result
}
#[cfg(not(target_arch = "wasm32"))]
fn compute_remote_visible_sections(
    start: RenderSectionKey,
    render_distance: u32,
    loaded_sections: &HashSet<RenderSectionKey>,
    visibility: &HashMap<RenderSectionKey, crate::render::chunk::VisibilitySet>,
) -> RemoteVisibleSections {
    if !loaded_sections.contains(&start) {
        return RemoteVisibleSections::from_unique_keys_with_capacity(
            visibility.len(),
            visibility.keys().copied().filter(|&key| {
                section_within_effective_render_distance_like_java(key, start, render_distance)
            }),
        );
    }
    let mut visible = Vec::new();
    let mut visible_set = HashSet::new();
    let mut visited = HashSet::new();
    let mut queue = VecDeque::from([(start, None)]);
    visited.insert((start, None));
    while let Some((key, entry_face)) = queue.pop_front() {
        if section_within_effective_render_distance_like_java(key, start, render_distance)
            && visibility.contains_key(&key)
            && visible_set.insert(key)
        {
            visible.push(key);
        }
        for exit_face in Direction::VALUES {
            if let Some(entry_face) = entry_face
                && visibility
                    .get(&key)
                    .is_some_and(|mesh| !mesh.visibility_between(entry_face, exit_face))
            {
                continue;
            }
            let (dx, dy, dz) = exit_face.step();
            let next =
                RenderSectionKey::new(key.chunk_x + dx, key.section_y + dy, key.chunk_z + dz);
            let next_entry = Some(exit_face.opposite());
            if loaded_sections.contains(&next)
                && section_within_effective_render_distance_like_java(next, start, render_distance)
                && visited.insert((next, next_entry))
            {
                queue.push_back((next, next_entry));
            }
        }
    }
    RemoteVisibleSections { ordered: visible }
}
