fn uses_java_entity_cutout_pipeline(kind: Option<VanillaEntityModelKind>, is_baby: bool) -> bool {
    !matches!(
        kind,
        None | Some(
            VanillaEntityModelKind::Arrow
                | VanillaEntityModelKind::Bat
                | VanillaEntityModelKind::Trident
        )
    ) && !(matches!(kind, Some(VanillaEntityModelKind::Turtle)) && is_baby)
}
fn uses_java_entity_cutout_cull_pipeline(
    kind: Option<VanillaEntityModelKind>,
    is_baby: bool,
) -> bool {
    matches!(
        kind,
        Some(VanillaEntityModelKind::Arrow | VanillaEntityModelKind::Bat)
    ) || (matches!(kind, Some(VanillaEntityModelKind::Turtle)) && is_baby)
}
