fn falling_block_render_block_pos_like_java(position: glam::Vec3) -> BlockPos {
    BlockPos::new(
        position.x.floor() as i32,
        (position.y + JAVA_FALLING_BLOCK_HEIGHT).floor() as i32,
        position.z.floor() as i32,
    )
}
fn apply_falling_block_renderer_pose_like_java(
    vertices: &mut [Vertex],
    interpolated_entity_position: glam::Vec3,
) {
    let translation = interpolated_entity_position + glam::Vec3::new(-0.5, 0.0, -0.5);
    for vertex in vertices {
        vertex.position[0] += translation.x;
        vertex.position[1] += translation.y;
        vertex.position[2] += translation.z;
    }
}
fn apply_moving_piston_renderer_pose_at_origin_like_java(
    vertices: &mut [Vertex],
    block_entity_pose_origin: glam::Vec3,
    translated_offset: glam::Vec3,
) {
    let translation = block_entity_pose_origin + translated_offset;
    for vertex in vertices {
        vertex.position[0] += translation.x;
        vertex.position[1] += translation.y;
        vertex.position[2] += translation.z;
    }
}
#[allow(dead_code)]
fn apply_moving_piston_renderer_pose_like_java(
    vertices: &mut [Vertex],
    block_entity_pos: BlockPos,
    translated_offset: glam::Vec3,
) {
    apply_moving_piston_renderer_pose_at_origin_like_java(
        vertices,
        glam::Vec3::new(
            block_entity_pos.x as f32,
            block_entity_pos.y as f32,
            block_entity_pos.z as f32,
        ),
        translated_offset,
    );
}
fn tnt_swell_amount_like_java(fuse_remaining_in_ticks: f32) -> f32 {
    let g = (1.0 - fuse_remaining_in_ticks / 10.0).clamp(0.0, 1.0);
    let g2 = g * g;
    g2 * g2 * 0.3
}
fn tnt_is_lit_like_java(fuse_remaining_in_ticks: f32) -> bool {
    fuse_remaining_in_ticks >= 0.0 && (fuse_remaining_in_ticks / 5.0).floor() as i32 % 2 == 0
}
fn apply_tnt_renderer_pose_like_java(vertices: &mut [Vertex], fuse_remaining_in_ticks: f32) {
    let mut pose = glam::Mat4::from_translation(glam::Vec3::new(0.0, 0.5, 0.0));
    if fuse_remaining_in_ticks < 10.0 {
        let scale = 1.0 + tnt_swell_amount_like_java(fuse_remaining_in_ticks);
        pose *= glam::Mat4::from_scale(glam::Vec3::splat(scale));
    }
    pose *= glam::Mat4::from_rotation_y(-90.0_f32.to_radians());
    pose *= glam::Mat4::from_translation(glam::Vec3::new(-0.5, -0.5, 0.5));
    pose *= glam::Mat4::from_rotation_y(90.0_f32.to_radians());
    for vertex in vertices {
        vertex.position = pose
            .transform_point3(glam::Vec3::from(vertex.position))
            .to_array();
        vertex.normal = pose
            .transform_vector3(glam::Vec3::from(vertex.normal))
            .normalize_or_zero()
            .to_array();
    }
}
fn falling_block_should_render_like_java(
    entity: &RemoteEntityRenderState,
    level: &ClientLevel,
    camera_position: glam::Vec3,
    view_scale: f32,
    frustum: crate::render::chunk::Frustum,
) -> bool {
    let position = entity.position;
    let distance_squared = position.distance_squared(camera_position) as f64;
    let distance_limit = f64::from(JAVA_FALLING_BLOCK_HEIGHT * 64.0 * view_scale);
    if !(distance_squared < distance_limit * distance_limit) {
        return false;
    }
    let half_width = JAVA_FALLING_BLOCK_WIDTH * 0.5 + 0.5;
    let cull_min = glam::Vec3::new(
        position.x - half_width,
        position.y - 0.5,
        position.z - half_width,
    );
    let cull_max = glam::Vec3::new(
        position.x + half_width,
        position.y + JAVA_FALLING_BLOCK_HEIGHT + 0.5,
        position.z + half_width,
    );
    if !frustum.contains_aabb(cull_min, cull_max) {
        return false;
    }
    entity.falling_block_state
        != level.get_block_state(falling_block_entity_block_pos_like_java(position))
}
