fn vanilla_bed_orientation_yaw_degrees(level: &ClientLevel, pos: BlockPos) -> Option<f32> {
    let state = level.get_block_state(pos);
    if state.block.namespace != "minecraft"
        || !matches!(
            state.block.path.as_str(),
            "white_bed"
                | "orange_bed"
                | "magenta_bed"
                | "light_blue_bed"
                | "yellow_bed"
                | "lime_bed"
                | "pink_bed"
                | "gray_bed"
                | "light_gray_bed"
                | "cyan_bed"
                | "purple_bed"
                | "blue_bed"
                | "brown_bed"
                | "green_bed"
                | "red_bed"
                | "black_bed"
        )
    {
        return None;
    }
    match state.get_property("facing").map(String::as_str) {
        Some("south") => Some(0.0),
        Some("west") => Some(90.0),
        Some("north") => Some(180.0),
        Some("east") => Some(270.0),
        _ => None,
    }
}
