fn remote_entity_texture_path_for_render(entity: &RemoteEntityRenderState) -> Option<&'static str> {
    let key = remote_entity_type_key(&entity.kind);
    if key == "arrow" && entity.arrow_effect_color > 0 {
        return Some("entity/projectiles/arrow_tipped");
    }
    if key == "camel" && entity.is_baby {
        return Some("entity/camel/camel_baby");
    }
    if (key == "piglin" || key == "piglin_brute") && entity.is_baby {
        return Some("entity/piglin/piglin_baby");
    }
    if key == "zombified_piglin" && entity.is_baby {
        return Some("entity/piglin/zombified_piglin_baby");
    }
    vanilla_entity_texture_path(&entity.kind)
}
