fn light_at_probe_position(level: Option<&ClientLevel>, probe_position: glam::Vec3) -> [f32; 2] {
    let Some(level) = level else {
        return [15.0 / 16.0, 15.0 / 16.0];
    };
    let pos = BlockPos::new(
        probe_position.x.floor() as i32,
        probe_position.y.floor() as i32,
        probe_position.z.floor() as i32,
    );
    packed_lightmap_factors(level.brightness(false, pos), level.brightness(true, pos))
}
