#[allow(dead_code)]
fn fishing_line_mesh_like_java(
    hook_position: glam::Vec3,
    owner_position: glam::Vec3,
    owner_body_yaw: f32,
    owner_crouching: bool,
    owner_main_arm_right: bool,
    owner_main_hand_is_rod: bool,
    _owner_attack_anim: f32,
    first_person_hand_position: Option<glam::Vec3>,
    line_width: f32,
) -> (Vec<LineVertex>, Vec<u32>) {
    let holding_arm_right = if owner_main_hand_is_rod {
        owner_main_arm_right
    } else {
        !owner_main_arm_right
    };
    let invert = if holding_arm_right { 1.0 } else { -1.0 };
    let hand_position = first_person_hand_position.unwrap_or_else(|| {
        let eye_height = if owner_crouching { 1.27 } else { 1.62 };
        let eye_position = owner_position + glam::Vec3::Y * eye_height;
        let sin = owner_body_yaw.sin();
        let cos = owner_body_yaw.cos();
        eye_position
            + glam::Vec3::new(
                -cos * invert * 0.35 - sin * 0.8,
                if owner_crouching { -0.1875 } else { 0.0 } - 0.45,
                -sin * invert * 0.35 + cos * 0.8,
            )
    });
    let line_origin = hand_position - (hook_position + glam::Vec3::Y * 0.25);
    fishing_line_mesh_from_line_origin_like_java(hook_position, line_origin, line_width)
}
fn fishing_line_mesh_from_line_origin_like_java(
    hook_position: glam::Vec3,
    line_origin: glam::Vec3,
    line_width: f32,
) -> (Vec<LineVertex>, Vec<u32>) {
    let mut vertices = Vec::with_capacity(16 * 4);
    let mut indices = Vec::with_capacity(16 * 6);
    for segment in 0..16 {
        let a0 = segment as f32 / 16.0;
        let a1 = (segment + 1) as f32 / 16.0;
        let point = |a: f32| {
            hook_position
                + glam::Vec3::new(
                    line_origin.x * a,
                    line_origin.y * (a * a + a) * 0.5 + 0.25,
                    line_origin.z * a,
                )
        };
        let first = point(a0);
        let second = point(a1);
        let direction = (second - first).normalize_or_zero().to_array();
        append_line_outline_quad(
            &mut vertices,
            &mut indices,
            first.to_array(),
            second.to_array(),
            [0.0, 0.0, 0.0, 1.0],
            direction,
            line_width,
        );
    }
    (vertices, indices)
}
