fn warn_skipped_frame_mesh_once(label: &str) {
    static WARNED: OnceLock<()> = OnceLock::new();
    if WARNED.set(()).is_ok() {
        log::warn!("[FrameArena] skipping {label}: expected non-empty frame mesh was unavailable");
    }
}
fn append_remote_player_frame_meshes(
    mesh: &RemotePlayerModelMesh,
    visibility: crate::render::model_frame::ModelVisibility,
    skin_available: bool,
    arena: &mut FrameMeshArena,
) -> (Option<FrameMeshSlice>, [Vec<FrameMeshSlice>; 4]) {
    let body = if crate::render::model_frame::should_submit_textured_world_body(visibility)
        && skin_available
    {
        let color = crate::render::model_frame::world_body_color(visibility);
        if color[3] < 1.0 {
            let mut vertices = mesh.vertices.clone();
            for vertex in &mut vertices {
                vertex.color[3] *= color[3];
            }
            arena.append_indexed(&vertices, &mesh.indices)
        } else {
            arena.append_indexed(&mesh.vertices, &mesh.indices)
        }
    } else {
        None
    };
    let armor = std::array::from_fn(|index| {
        if visibility.is_spectator {
            return Vec::new();
        }
        mesh.armor[index]
            .as_ref()
            .map(|armor| {
                armor
                    .layers
                    .iter()
                    .filter_map(|layer| arena.append_indexed(&layer.vertices, &layer.indices))
                    .collect()
            })
            .unwrap_or_default()
    });
    (body, armor)
}
