fn rendered_dropped_item_amount(stack_count: i32) -> usize {
    match stack_count {
        i32::MIN..=1 => 1,
        2..=16 => 2,
        17..=32 => 3,
        33..=48 => 4,
        _ => 5,
    }
}
fn dropped_item_seed(stack: &ItemStack) -> i64 {
    if stack.is_empty() {
        return 187;
    }
    let item_id = BuiltInRegistries::items().get_id(&stack.item.location) as i64;
    item_id + stack.get_damage_value() as i64
}
struct LegacyItemRandom {
    seed: u64,
}
impl LegacyItemRandom {
    const MASK: u64 = (1_u64 << 48) - 1;
    const MULTIPLIER: u64 = 25_214_903_917;
    const ADDEND: u64 = 11;
    fn new(seed: i64) -> Self {
        Self {
            seed: ((seed as u64) ^ Self::MULTIPLIER) & Self::MASK,
        }
    }
    fn next(&mut self, bits: u32) -> u32 {
        self.seed = self
            .seed
            .wrapping_mul(Self::MULTIPLIER)
            .wrapping_add(Self::ADDEND)
            & Self::MASK;
        (self.seed >> (48 - bits)) as u32
    }
    fn next_float(&mut self) -> f32 {
        self.next(24) as f32 / ((1_u32 << 24) as f32)
    }
}
fn dropped_item_copy_offsets(
    stack: &ItemStack,
    bounds: ItemMeshBounds,
) -> ([glam::Mat4; 5], usize) {
    const OFFSET_SCALE: f32 = 0.15;
    const FLAT_DEPTH_THRESHOLD: f32 = 0.0625;
    let amount = rendered_dropped_item_amount(stack.count);
    let mut offsets = [glam::Mat4::IDENTITY; 5];
    let mut random = LegacyItemRandom::new(dropped_item_seed(stack));
    let model_depth = bounds.z_size();
    if model_depth > FLAT_DEPTH_THRESHOLD {
        offsets[0] = glam::Mat4::IDENTITY;
        for i in 1..amount {
            let xo = (random.next_float() * 2.0 - 1.0) * OFFSET_SCALE;
            let yo = (random.next_float() * 2.0 - 1.0) * OFFSET_SCALE;
            let zo = (random.next_float() * 2.0 - 1.0) * OFFSET_SCALE;
            offsets[i] = glam::Mat4::from_translation(glam::Vec3::new(xo, yo, zo));
        }
    } else {
        let offset_z = model_depth * 1.5;
        let start_z = -(offset_z * (amount.saturating_sub(1) as f32) / 2.0);
        for i in 0..amount {
            let z = start_z + offset_z * i as f32;
            if i == 0 {
                offsets[0] = glam::Mat4::from_translation(glam::Vec3::new(0.0, 0.0, z));
            } else {
                let xo = (random.next_float() * 2.0 - 1.0) * OFFSET_SCALE * 0.5;
                let yo = (random.next_float() * 2.0 - 1.0) * OFFSET_SCALE * 0.5;
                offsets[i] = glam::Mat4::from_translation(glam::Vec3::new(xo, yo, z));
            }
        }
    }
    (offsets, amount)
}
