#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RemoteSectionMeshInvalidation {
    key: RenderSectionKey,
    urgent: bool,
    last_urgent_order: Option<usize>,
}
#[derive(Default)]
struct RemoteSectionMeshInvalidationBatch {
    entries: Vec<RemoteSectionMeshInvalidation>,
    indices: HashMap<RenderSectionKey, usize>,
    next_urgent_order: usize,
}
impl RemoteSectionMeshInvalidationBatch {
    fn push(&mut self, key: RenderSectionKey, urgent: bool) {
        let index = if let Some(&index) = self.indices.get(&key) {
            index
        } else {
            let index = self.entries.len();
            self.entries.push(RemoteSectionMeshInvalidation {
                key,
                urgent: false,
                last_urgent_order: None,
            });
            self.indices.insert(key, index);
            index
        };
        if urgent {
            let entry = &mut self.entries[index];
            entry.urgent = true;
            entry.last_urgent_order = Some(self.next_urgent_order);
            self.next_urgent_order = self.next_urgent_order.wrapping_add(1);
        }
    }
    fn into_queue_calls(self) -> Vec<RemoteSectionMeshInvalidation> {
        let mut queue_calls = Vec::with_capacity(self.entries.len());
        let mut urgent = Vec::new();
        for entry in self.entries {
            if entry.urgent {
                urgent.push(entry);
            } else {
                queue_calls.push(entry);
            }
        }
        urgent.sort_unstable_by_key(|entry| entry.last_urgent_order);
        queue_calls.extend(urgent);
        queue_calls
    }
}
