impl RemoteVisibleSections {
    fn from_unique_keys_with_capacity(
        capacity: usize,
        keys: impl IntoIterator<Item = RenderSectionKey>,
    ) -> Self {
        let mut ordered = Vec::with_capacity(capacity);
        ordered.extend(keys);
        Self { ordered }
    }
    fn len(&self) -> usize {
        self.ordered.len()
    }
    fn keys(&self) -> &[RenderSectionKey] {
        &self.ordered
    }
}
fn section_within_effective_render_distance_like_java(
    key: RenderSectionKey,
    camera_section: RenderSectionKey,
    render_distance: u32,
) -> bool {
    let radius = i64::from(render_distance);
    (i64::from(key.chunk_x) - i64::from(camera_section.chunk_x)).abs() <= radius
        && (i64::from(key.chunk_z) - i64::from(camera_section.chunk_z)).abs() <= radius
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RemoteMeshQueueClass {
    Urgent,
    Initial,
    Recompile,
}
#[derive(Debug)]
struct RemoteMeshUrgentInFlight {
    generation: u64,
    count: usize,
}
impl RemoteMeshUrgentInFlight {
    fn new(generation: u64) -> Self {
        Self {
            generation,
            count: 0,
        }
    }
    fn reset(&mut self, generation: u64) {
        self.generation = generation;
        self.count = 0;
    }
    fn can_dispatch(&self, generation: u64) -> bool {
        self.generation == generation && self.count < REMOTE_RENDER_URGENT_IN_FLIGHT_LIMIT
    }
    fn available_slots(&self, generation: u64) -> usize {
        if self.generation == generation {
            REMOTE_RENDER_URGENT_IN_FLIGHT_LIMIT.saturating_sub(self.count)
        } else {
            0
        }
    }
    fn record_dispatch(&mut self, generation: u64) {
        debug_assert_eq!(self.generation, generation);
        debug_assert!(self.count < REMOTE_RENDER_URGENT_IN_FLIGHT_LIMIT);
        self.count += 1;
    }
    fn record_result(&mut self, generation: u64) {
        if crate::render::mesh_revision::should_count_urgent_result(self.generation, generation) {
            debug_assert!(self.count > 0);
            self.count = self.count.saturating_sub(1);
        }
    }
}
