struct RemoteMeshCommitSink<'a> {
    queue: &'a mut crate::render::mesh_queue::RemoteMeshQueue<RenderSectionKey>,
    urgent_in_flight: &'a mut RemoteMeshUrgentInFlight,
    compiled: &'a mut HashSet<RenderSectionKey>,
    meshes: &'a mut HashMap<RenderSectionKey, GpuChunkMesh>,
    traces: &'a mut HashMap<RenderSectionKey, BlockRenderTrace>,
    arena: &'a mut TerrainGpuArena,
    device: &'a wgpu::Device,
    level: &'a Option<ClientLevel>,
    visibility_revision: &'a mut u64,
    translucent_resort_pending: &'a mut bool,
}
impl<'a> RemoteMeshCommitSink<'a> {
    fn invalidate_remote_visibility(&mut self) {
        *self.visibility_revision = self.visibility_revision.wrapping_add(1);
        *self.translucent_resort_pending = true;
    }
    fn remove_remote_section_mesh(&mut self, key: &RenderSectionKey) -> bool {
        let Some(mesh) = self.meshes.remove(key) else {
            return false;
        };
        self.arena.free(mesh.allocation);
        true
    }
}
impl<'a> crate::render::mesh_result::MeshCommitSink<RenderSectionKey, RemoteSectionMeshResult>
    for RemoteMeshCommitSink<'a>
{
    fn on_urgent_result(&mut self, generation: u64) {
        self.urgent_in_flight.record_result(generation);
    }
    fn confirm_completion(&mut self, key: RenderSectionKey, revision: u64, urgent: bool) {
        self.queue.confirm_completion(key, revision, urgent);
    }
    fn current_revision(&self, key: RenderSectionKey) -> Option<u64> {
        self.queue.revision(key)
    }
    fn chunk_loaded(&self, key: RenderSectionKey) -> bool {
        self.level
            .as_ref()
            .is_some_and(|level| level.chunks.contains_key(&key.chunk_pos()))
    }
    fn commit_one(
        &mut self,
        result: RemoteSectionMeshResult,
        _meta: crate::render::mesh_result::MeshResultMeta<RenderSectionKey>,
        verdict: crate::render::mesh_result::CommitVerdict,
    ) {
        use crate::render::mesh_result::CommitVerdict;
        match verdict {
            CommitVerdict::RetireCancelled | CommitVerdict::DropStale => return,
            CommitVerdict::EvictUnloaded => {
                if self.remove_remote_section_mesh(&result.key) {
                    self.invalidate_remote_visibility();
                }
                self.compiled.remove(&result.key);
                return;
            }
            CommitVerdict::RetireEmpty => {
                self.compiled.insert(result.key);
                if self.remove_remote_section_mesh(&result.key) {
                    self.invalidate_remote_visibility();
                }
                if let Some(trace_context) = result.block_trace {
                    let now = Instant::now();
                    if let Some(trace) = self.traces.get_mut(&result.key)
                        && trace.id == trace_context.id
                        && trace.revision == result.revision
                    {
                        trace.uploaded_at = Some(now);
                    }
                    if DEBUG_VERBOSE_BLOCK_TRACE {
                        println!(
                            "[BlockTrace #{}] GPU_REMOVE_EMPTY revision={} section=[{}, {}, {}] total={:.2}ms",
                            trace_context.id,
                            result.revision,
                            result.key.chunk_x,
                            result.key.section_y,
                            result.key.chunk_z,
                            now.duration_since(trace_context.action_started_at)
                                .as_secs_f64()
                                * 1000.0,
                        );
                    }
                }
                return;
            }
            CommitVerdict::Upload => {}
        }
        let gpu_upload_started_at = Instant::now();
        let vertex_count = result.vertices.len();
        let vertices = result.vertices;
        let opaque_indices = result.indices.len() as u32;
        let translucent_start = opaque_indices;
        let translucent_indices = result.translucent_indices.len() as u32;
        let translucent_quads = result.translucent_quads;
        let translucency_point_of_view = result.translucency_point_of_view;
        let translucent_sort_block = result.translucent_sort_block;
        let mut combined_indices = result.indices;
        combined_indices.extend(result.translucent_indices);
        let visibility_changed = self
            .meshes
            .get(&result.key)
            .is_none_or(|mesh| mesh.visibility != result.visibility);
        let previous_allocation = self.meshes.get(&result.key).map(|mesh| mesh.allocation);
        let staged =
            self.arena
                .stage_upload(self.device, previous_allocation, vertices, combined_indices);
        let staged = staged.map_err(|error| {
            log::error!(
                "[terrain] failed to reserve remote section [{}, {}, {}]: {error:?}",
                result.key.chunk_x,
                result.key.section_y,
                result.key.chunk_z,
            );
        });
        let allocation =
            match crate::render::mesh_upload::resolve_staged_upload(previous_allocation, staged) {
                crate::render::mesh_upload::StagedUpload::KeepOld { .. } => return,
                crate::render::mesh_upload::StagedUpload::Published {
                    live: allocation, ..
                } => allocation,
            };
        let key = result.key;
        self.compiled.insert(key);
        self.meshes.insert(
            key,
            GpuChunkMesh {
                allocation,
                opaque_indices,
                translucent_start,
                translucent_indices,
                translucent_quads,
                translucency_point_of_view,
                translucent_sort_block,
                visibility: result.visibility,
            },
        );
        if visibility_changed {
            self.invalidate_remote_visibility();
        }
        let gpu_upload_finished_at = Instant::now();
        let gpu_upload_ms = gpu_upload_finished_at
            .duration_since(gpu_upload_started_at)
            .as_secs_f64()
            * 1000.0;
        if let Some(trace_context) = result.block_trace {
            if let Some(trace) = self.traces.get_mut(&key)
                && trace.id == trace_context.id
                && trace.revision == result.revision
            {
                trace.uploaded_at = Some(gpu_upload_finished_at);
            }
            if DEBUG_VERBOSE_BLOCK_TRACE {
                println!(
                    "[BlockTrace #{}] GPU_UPLOAD revision={} section=[{}, {}, {}] worker_queue={:.2}ms mesh={:.2}ms result_wait={:.2}ms upload={gpu_upload_ms:.2}ms total={:.2}ms",
                    trace_context.id,
                    result.revision,
                    key.chunk_x,
                    key.section_y,
                    key.chunk_z,
                    result
                        .mesh_started_at
                        .duration_since(result.submitted_at)
                        .as_secs_f64()
                        * 1000.0,
                    result
                        .mesh_finished_at
                        .duration_since(result.mesh_started_at)
                        .as_secs_f64()
                        * 1000.0,
                    gpu_upload_started_at
                        .duration_since(result.mesh_finished_at)
                        .as_secs_f64()
                        * 1000.0,
                    gpu_upload_finished_at
                        .duration_since(trace_context.action_started_at)
                        .as_secs_f64()
                        * 1000.0,
                );
            }
        } else if (should_log_lag_reports() || gpu_upload_ms >= 15.0) && gpu_upload_ms >= 10.0 {
            let msg = format!(
                "[Lag][GpuUpload] section=[{}, {}, {}] upload={gpu_upload_ms:.2}ms vertices={} indices={}",
                key.chunk_x,
                key.section_y,
                key.chunk_z,
                vertex_count,
                opaque_indices + translucent_indices,
            );
            emit_lag_log(&msg);
        }
    }
}
#[cfg(target_arch = "wasm32")]
fn wasm_channel_send_timeout<T>(
    sender: &crossbeam_channel::Sender<T>,
    mut message: T,
    timeout: Duration,
) -> Result<(), Option<T>> {
    let deadline = Instant::now() + timeout;
    loop {
        match sender.try_send(message) {
            Ok(()) => return Ok(()),
            Err(crossbeam_channel::TrySendError::Full(returned)) => {
                message = returned;
                if Instant::now() >= deadline {
                    return Err(Some(message));
                }
                std::hint::spin_loop();
            }
            Err(crossbeam_channel::TrySendError::Disconnected(_)) => return Err(None),
        }
    }
}
fn send_remote_mesh_result_with_generation_backpressure(
    sender: &crossbeam_channel::Sender<RemoteSectionMeshResult>,
    completion_sender: &mpsc::Sender<RemoteSectionMeshCompletion>,
    generation_fence: &AtomicU64,
    compile_revision: &AtomicU64,
    mut result: RemoteSectionMeshResult,
) -> bool {
    const GENERATION_RECHECK_INTERVAL: Duration = Duration::from_millis(2);
    loop {
        match crate::render::mesh_revision::worker_send_verdict(
            generation_fence.load(Ordering::Acquire),
            compile_revision.load(Ordering::Acquire),
            result.generation,
            result.revision,
        ) {
            crate::render::mesh_revision::WorkerSendVerdict::Drop => return true,
            crate::render::mesh_revision::WorkerSendVerdict::CompleteLightlyAndDrop => {
                return completion_sender.send(result.completion()).is_ok();
            }
            crate::render::mesh_revision::WorkerSendVerdict::Send => {}
        }
        #[cfg(target_arch = "wasm32")]
        match wasm_channel_send_timeout(sender, result, GENERATION_RECHECK_INTERVAL) {
            Ok(()) => return true,
            Err(Some(returned)) => {
                result = returned;
            }
            Err(None) => return false,
        }
        #[cfg(not(target_arch = "wasm32"))]
        match sender.send_timeout(result, GENERATION_RECHECK_INTERVAL) {
            Ok(()) => return true,
            Err(crossbeam_channel::SendTimeoutError::Timeout(returned)) => {
                result = returned;
            }
            Err(crossbeam_channel::SendTimeoutError::Disconnected(_)) => return false,
        }
    }
}
