#[derive(Default)]
struct DynamicGpuMesh {
    vertex_buffer: Option<wgpu::Buffer>,
    index_buffer: Option<wgpu::Buffer>,
    vertex_capacity: usize,
    index_capacity: usize,
    index_count: u32,
}
impl DynamicGpuMesh {
    fn update(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        mesh: &ChunkMesh,
        label: &str,
    ) {
        self.update_from_parts(device, queue, &mesh.vertices, &mesh.indices, label);
    }
    fn update_from_parts<V: bytemuck::Pod>(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        vertices: &[V],
        indices: &[u32],
        label: &str,
    ) {
        self.index_count = indices.len() as u32;
        if self.index_count == 0 {
            return;
        }
        let vertex_bytes = bytemuck::cast_slice(vertices);
        if let Some(buffer) = self
            .vertex_buffer
            .as_ref()
            .filter(|_| vertex_bytes.len() <= self.vertex_capacity)
        {
            queue.write_buffer(buffer, 0, vertex_bytes);
        } else {
            let capacity = vertex_bytes.len().next_power_of_two().max(16384);
            self.vertex_buffer = Some(device.create_buffer(&wgpu::BufferDescriptor {
                label: Some(&format!("{label} Vertex Buffer")),
                size: capacity as u64,
                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
                mapped_at_creation: false,
            }));
            self.vertex_capacity = capacity;
            if let Some(buffer) = &self.vertex_buffer {
                queue.write_buffer(buffer, 0, vertex_bytes);
            }
        }
        let index_bytes = bytemuck::cast_slice(indices);
        if let Some(buffer) = self
            .index_buffer
            .as_ref()
            .filter(|_| index_bytes.len() <= self.index_capacity)
        {
            queue.write_buffer(buffer, 0, index_bytes);
        } else {
            let capacity = index_bytes.len().next_power_of_two().max(4096);
            self.index_buffer = Some(device.create_buffer(&wgpu::BufferDescriptor {
                label: Some(&format!("{label} Index Buffer")),
                size: capacity as u64,
                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
                mapped_at_creation: false,
            }));
            self.index_capacity = capacity;
            if let Some(buffer) = &self.index_buffer {
                queue.write_buffer(buffer, 0, index_bytes);
            }
        }
    }
}
