#[allow(clippy::too_many_arguments)]
fn apply_remote_scoreboard_team_update(
    teams: &mut HashMap<String, ClientTeamState>,
    teams_by_player: &mut HashMap<String, String>,
    name: String,
    op: u8,
    collision_rule: Option<String>,
    members: Option<Vec<String>>,
    nametag_visibility: Option<String>,
    team_options: Option<u8>,
) {
    fn add_members(
        teams: &mut HashMap<String, ClientTeamState>,
        teams_by_player: &mut HashMap<String, String>,
        team_name: &str,
        members: Vec<String>,
    ) {
        for member in members {
            if let Some(old_team_name) =
                teams_by_player.insert(member.clone(), team_name.to_owned())
            {
                if old_team_name != team_name {
                    if let Some(old_team) = teams.get_mut(&old_team_name) {
                        old_team.members.remove(&member);
                    }
                }
            }
            if let Some(team) = teams.get_mut(team_name) {
                team.members.insert(member);
            }
        }
    }
    match op {
        0 => {
            let team = teams.entry(name.clone()).or_default();
            if let Some(collision_rule) = collision_rule {
                team.collision_rule = collision_rule;
            }
            if let Some(nametag_visibility) = nametag_visibility {
                team.nametag_visibility = nametag_visibility;
            }
            if let Some(team_options) = team_options {
                team.options = team_options;
            }
            if let Some(members) = members {
                add_members(teams, teams_by_player, &name, members);
            }
        }
        1 => {
            if let Some(team) = teams.remove(&name) {
                for member in team.members {
                    if teams_by_player.get(&member) == Some(&name) {
                        teams_by_player.remove(&member);
                    }
                }
            }
        }
        2 => {
            if let Some(team) = teams.get_mut(&name) {
                if let Some(collision_rule) = collision_rule {
                    team.collision_rule = collision_rule;
                }
                if let Some(nametag_visibility) = nametag_visibility {
                    team.nametag_visibility = nametag_visibility;
                }
                if let Some(team_options) = team_options {
                    team.options = team_options;
                }
            }
        }
        3 if teams.contains_key(&name) => {
            if let Some(members) = members {
                add_members(teams, teams_by_player, &name, members);
            }
        }
        4 if teams.contains_key(&name) => {
            if let Some(members) = members {
                for member in members {
                    if teams_by_player.get(&member) == Some(&name) {
                        teams_by_player.remove(&member);
                        if let Some(team) = teams.get_mut(&name) {
                            team.members.remove(&member);
                        }
                    }
                }
            }
        }
        _ => {}
    }
}
