#[derive(Debug)]
struct RemoteChunkRingSlots {
    storage_radius: i32,
    slots: Vec<Option<ChunkPos>>,
}
impl RemoteChunkRingSlots {
    fn new(storage_radius: i32) -> Self {
        let view_range = storage_radius * 2 + 1;
        Self {
            storage_radius,
            slots: vec![None; (view_range * view_range) as usize],
        }
    }
    fn replace(&mut self, incoming: ChunkPos) -> Option<ChunkPos> {
        let index = State::remote_storage_slot_index(incoming, self.storage_radius) as usize;
        let previous = self.slots[index].replace(incoming);
        previous.filter(|previous| *previous != incoming)
    }
    fn clear_if_matches(&mut self, chunk: ChunkPos) -> bool {
        let index = State::remote_storage_slot_index(chunk, self.storage_radius) as usize;
        if self.slots[index] == Some(chunk) {
            self.slots[index] = None;
            true
        } else {
            false
        }
    }
    fn clear(&mut self) {
        self.slots.fill(None);
    }
    fn rebuild(&mut self, storage_radius: i32, view_center: Option<(i32, i32)>) -> Vec<ChunkPos> {
        if self.storage_radius == storage_radius {
            return Vec::new();
        }
        let old_slots = std::mem::replace(self, Self::new(storage_radius)).slots;
        let mut evicted = Vec::new();
        for chunk in old_slots.into_iter().flatten() {
            if view_center.is_some_and(|center| {
                !State::chunk_within_radius(center, chunk.x, chunk.z, storage_radius)
            }) {
                evicted.push(chunk);
            } else if let Some(replaced) = self.replace(chunk) {
                evicted.push(replaced);
            }
        }
        evicted
    }
}
