    fn remote_mesh_result_will_upload(
        &self,
        result: &RemoteSectionMeshResult,
        meta: &crate::render::mesh_result::MeshResultMeta<RenderSectionKey>,
    ) -> bool {
        let chunk_loaded = self
            .session
            .level
            .as_ref()
            .is_some_and(|level| level.chunks.contains_key(&result.key.chunk_pos()));
        crate::render::mesh_result::result_will_upload(
            self.renderer.remote_mesh_generation,
            self.renderer.remote_mesh_queue.revision(result.key),
            chunk_loaded,
            meta,
        )
    }
    fn commit_remote_mesh_results(&mut self, results_to_commit: Vec<RemoteSectionMeshResult>) {
        let generation = self.renderer.remote_mesh_generation;
        let renderer = &mut self.renderer;
        let mut sink = RemoteMeshCommitSink {
            queue: &mut renderer.remote_mesh_queue,
            urgent_in_flight: &mut renderer.remote_mesh_urgent_in_flight,
            compiled: &mut renderer.remote_compiled_sections,
            meshes: &mut renderer.remote_section_meshes,
            traces: &mut renderer.remote_block_render_traces,
            arena: &mut renderer.remote_terrain_gpu_arena,
            device: &self.device,
            level: &self.session.level,
            visibility_revision: &mut renderer.remote_visibility_revision,
            translucent_resort_pending: &mut renderer.translucent_resort_pending,
        };
        crate::render::mesh_result::drive_mesh_commits(
            &mut sink,
            results_to_commit,
            RemoteSectionMeshResult::commit_meta,
            generation,
        );
    }
    fn process_remote_chunk_mesh_queue_mode(&mut self, urgent_only: bool) {
        if self.session.remote_connection.is_none() {
            return;
        }
        *self
            .renderer
            .remote_mesh_camera_position
            .write()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = self.camera.position;
        let results_to_commit = if !urgent_only {
            let completions =
                std::iter::from_fn(|| self.renderer.remote_mesh_completion_rx.try_recv().ok())
                    .map(|completion: RemoteSectionMeshCompletion| {
                        crate::render::mesh_result::MeshCompletion {
                            generation: completion.generation,
                            revision: completion.revision,
                            key: completion.key,
                            urgent: completion.urgent,
                        }
                    })
                    .collect::<Vec<_>>();
            let generation = self.renderer.remote_mesh_generation;
            crate::render::mesh_queue::drain_mesh_completions(
                completions.into_iter(),
                generation,
                |result_generation| {
                    self.renderer
                        .remote_mesh_urgent_in_flight
                        .record_result(result_generation);
                },
                |key, revision, urgent| {
                    self.renderer
                        .remote_mesh_queue
                        .confirm_completion(key, revision, urgent);
                },
            );
            let max_total_uploads = crate::render::mesh_upload::max_total_uploads(
                cfg!(target_arch = "wasm32"),
                REMOTE_RENDER_SECTION_UPLOADS_PER_FRAME,
            );
            let mut commit_budget = production_commit_budget(max_total_uploads);
            #[cfg(target_arch = "wasm32")]
            let upload_budget_start = Instant::now();
            #[cfg(target_arch = "wasm32")]
            const WASM_UPLOAD_MS_BUDGET: u64 = 2;
            #[cfg(target_arch = "wasm32")]
            let should_yield_for_time =
                || upload_budget_start.elapsed().as_millis() as u64 >= WASM_UPLOAD_MS_BUDGET;
            #[cfg(not(target_arch = "wasm32"))]
            let should_yield_for_time = || false;
            let batch = crate::render::mesh_queue::collect_mesh_commit_batch(
                self.renderer.remote_mesh_result_urgent_deferred.take(),
                self.renderer.remote_mesh_result_normal_deferred.take(),
                || self.renderer.remote_mesh_result_urgent_rx.try_recv().ok(),
                || self.renderer.remote_mesh_result_normal_rx.try_recv().ok(),
                RemoteSectionMeshResult::commit_meta,
                |result, meta| self.remote_mesh_result_will_upload(result, meta),
                should_yield_for_time,
                &mut commit_budget,
            );
            self.renderer.remote_mesh_result_urgent_deferred = batch.deferred_urgent;
            self.renderer.remote_mesh_result_normal_deferred = batch.deferred_normal;
            batch.commits
        } else {
            Vec::new()
        };
        self.commit_remote_mesh_results(results_to_commit);
        if urgent_only && self.renderer.remote_mesh_queue.urgent_len() == 0 {
            return;
        }
        if !self.renderer.remote_mesh_queue.is_empty() {
            let model_cache = self.remote_model_cache_for_mesh_jobs();
            let Some(block_colors) = self.remote_block_colors_for_mesh_jobs() else {
                return;
            };
            let generation = self.renderer.remote_mesh_generation;
            let biome_definitions = self
                .session
                .level
                .as_ref()
                .map(|level| Arc::clone(&level.biome_definitions))
                .unwrap_or_else(|| {
                    let plains = crate::render::block_colors::Biome::plains();
                    Arc::new(HashMap::from([(plains.id.clone(), plains)]))
                });
            let priority_batch_started_at = Instant::now();
            let dispatch_count = self.prepare_remote_mesh_dispatch_batch(
                urgent_only,
                REMOTE_RENDER_SECTION_SUBMITS_PER_FRAME,
            );
            self.renderer.render_profiler.observe(
                "State::update::mesh_queue_priority_batch",
                priority_batch_started_at.elapsed(),
            );
            for _ in 0..dispatch_count {
                let Some(key) = self.pop_remote_mesh_queue() else {
                    break;
                };
                let is_urgent = self.renderer.remote_mesh_queue.is_urgent(key);
                let same_priority_pending = self
                    .renderer
                    .remote_mesh_queue
                    .is_pending_in_lane(key, is_urgent);
                if same_priority_pending && !is_urgent {
                    self.renderer.remote_mesh_queue.requeue(key, false);
                    continue;
                }
                if !is_urgent
                    && self.renderer.remote_mesh_queue.pending_len()
                        >= REMOTE_RENDER_SECTION_PENDING_LIMIT
                {
                    self.renderer.remote_mesh_queue.requeue(key, true);
                    break;
                }
                if is_urgent
                    && !self
                        .renderer
                        .remote_mesh_urgent_in_flight
                        .can_dispatch(self.renderer.remote_mesh_generation)
                {
                    self.renderer.remote_mesh_queue.requeue(key, true);
                    break;
                }
                self.renderer.remote_mesh_queue.clear_urgent(key);
                let remote_center = self.remote_chunk_center();
                if self.remote_chunk_cache_center.is_some()
                    && !Self::chunk_within_radius(
                        remote_center,
                        key.chunk_x,
                        key.chunk_z,
                        self.remote_chunk_keep_radius,
                    )
                {
                    self.renderer.remote_mesh_queue.clear_pending(key, false);
                    self.renderer.remote_mesh_queue.clear_pending(key, true);
                    if self.remove_remote_section_mesh(&key) {
                        self.invalidate_remote_visibility();
                    }
                    continue;
                }
                let Some(job) = self
                    .renderer
                    .remote_chunk_snapshots
                    .get(&key.chunk_pos())
                    .and_then(|chunk| {
                        let revision = self.renderer.remote_mesh_queue.revision(key).unwrap_or(0);
                        let compile_revision = self
                            .renderer
                            .remote_section_compile_revisions
                            .get(&key)
                            .cloned()
                            .unwrap_or_else(|| Arc::new(AtomicU64::new(revision)));
                        let section_index = chunk
                            .sections
                            .iter()
                            .position(|section| section.y_index == key.section_y)?;
                        let neighbor_chunks = Self::neighbor_chunk_positions(key.chunk_pos())
                            .into_iter()
                            .filter_map(|pos| {
                                self.renderer.remote_chunk_snapshots.get(&pos).cloned()
                            })
                            .collect::<Vec<_>>();
                        let block_trace = self
                            .renderer
                            .remote_block_render_traces
                            .get(&key)
                            .filter(|trace| trace.revision == revision)
                            .map(|trace| BlockMeshTraceContext {
                                id: trace.id,
                                action_started_at: trace.action_started_at,
                                queued_at: trace.queued_at,
                            });
                        Some(RemoteSectionMeshJob {
                            generation,
                            generation_fence: Arc::clone(
                                &self.renderer.remote_mesh_generation_fence,
                            ),
                            revision,
                            key,
                            chunk: Arc::clone(chunk),
                            section_index,
                            neighbor_chunks,
                            model_cache: Arc::clone(&model_cache),
                            block_colors: Arc::clone(&block_colors),
                            biome_definitions: Arc::clone(&biome_definitions),
                            biome_blend_radius: self.biome_blend_radius(),
                            biome_zoom_seed: self
                                .session
                                .level
                                .as_ref()
                                .map(|level| level.biome_zoom_seed())
                                .unwrap_or(0),
                            ambient_occlusion_enabled: self.gui_manager.ambient_occlusion_enabled(),
                            camera_position: Arc::clone(&self.renderer.remote_mesh_camera_position),
                            urgent: is_urgent,
                            compile_revision,
                            submitted_at: Instant::now(),
                            block_trace,
                        })
                    })
                else {
                    self.renderer.remote_mesh_queue.clear_pending(key, false);
                    self.renderer.remote_mesh_queue.clear_pending(key, true);
                    if self.remove_remote_section_mesh(&key) {
                        self.invalidate_remote_visibility();
                    }
                    continue;
                };
                self.renderer
                    .remote_mesh_queue
                    .set_pending(key, job.revision, is_urgent);
                if let Some(trace) = job.block_trace {
                    if DEBUG_VERBOSE_BLOCK_TRACE {
                        println!(
                            "[BlockTrace #{}] DISPATCH revision={} section=[{}, {}, {}] queue={} pending={} elapsed={:.2}ms",
                            trace.id,
                            job.revision,
                            key.chunk_x,
                            key.section_y,
                            key.chunk_z,
                            self.renderer.remote_mesh_queue.len(),
                            self.renderer.remote_mesh_queue.pending_len(),
                            trace.action_started_at.elapsed().as_secs_f64() * 1000.0,
                        );
                    }
                }
                #[cfg(target_arch = "wasm32")]
                {
                    let result_tx = if is_urgent {
                        self.renderer.remote_mesh_result_urgent_tx.clone()
                    } else {
                        self.renderer.remote_mesh_result_normal_tx.clone()
                    };
                    let completion_tx = self.renderer.remote_mesh_completion_tx.clone();
                    if is_urgent {
                        self.renderer
                            .remote_mesh_urgent_in_flight
                            .record_dispatch(generation);
                    }
                    rayon::spawn(move || {
                        let generation_fence = Arc::clone(&job.generation_fence);
                        let compile_revision = Arc::clone(&job.compile_revision);
                        let result = Self::mesh_remote_section_job(job);
                        let _ = send_remote_mesh_result_with_generation_backpressure(
                            &result_tx,
                            &completion_tx,
                            generation_fence.as_ref(),
                            compile_revision.as_ref(),
                            result,
                        );
                    });
                }
                #[cfg(not(target_arch = "wasm32"))]
                {
                    let send_result = if is_urgent {
                        self.renderer.remote_mesh_urgent_job_tx.send(job)
                    } else {
                        self.renderer.remote_mesh_job_tx.send(job)
                    };
                    if send_result.is_err() {
                        self.renderer
                            .remote_mesh_queue
                            .clear_pending(key, is_urgent);
                        break;
                    }
                    if is_urgent {
                        self.renderer
                            .remote_mesh_urgent_in_flight
                            .record_dispatch(generation);
                    }
                }
            }
        }
        #[cfg(target_arch = "wasm32")]
        self.mark_wasm_remote_mesh_ready_after_sync();
    }
    #[cfg(not(target_arch = "wasm32"))]
    fn handle_native_block_event(
        &mut self,
        packet: &el_protocol::packets::game::ClientboundBlockEventPacket,
    ) {
        let pos = el_protocol_backend::BackendBlockPos {
            x: packet.pos.x,
            y: packet.pos.y,
            z: packet.pos.z,
        };
        self.handle_remote_network_event(el_protocol_backend::BackendNetworkEvent::BlockEvent {
            pos,
            action_id: packet.b0,
            action_parameter: packet.b1,
        });
    }
    #[cfg(not(target_arch = "wasm32"))]
    fn handle_native_sound(&mut self, packet: el_protocol::packets::game::ClientboundSoundPacket) {
        let (x, y, z) = packet.position();
        self.handle_remote_network_event(el_protocol_backend::BackendNetworkEvent::Sound {
            sound: packet.sound,
            source: packet.source as u8,
            x,
            y,
            z,
            volume: packet.volume,
            pitch: packet.pitch,
            seed: packet.seed as u64,
            fixed_range: packet.fixed_range,
        });
    }
    #[cfg(not(target_arch = "wasm32"))]
    fn handle_play_packet(&mut self, packet_id: i32, payload: Vec<u8>) {
        use el_protocol::packets::game::{
            ClientboundAddEntityPacket, ClientboundBlockEntityDataPacket,
            ClientboundBlockEventPacket, ClientboundBlockUpdatePacket,
            ClientboundChangeDifficultyPacket, ClientboundChunkBatchFinishedPacket,
            ClientboundChunkBatchStartPacket, ClientboundContainerClosePacket,
            ClientboundContainerSetContentPacket, ClientboundContainerSetDataPacket,
            ClientboundContainerSetSlotPacket, ClientboundDisconnectPacket,
            ClientboundGameEventPacket, ClientboundLevelChunkWithLightPacket,
            ClientboundLevelEventPacket, ClientboundLoginPacket, ClientboundOpenScreenPacket,
            ClientboundPlayerPositionPacket, ClientboundPlayerRotationPacket,
            ClientboundRespawnPacket, ClientboundSectionBlocksUpdatePacket,
            ClientboundSetCursorItemPacket, ClientboundSetExperiencePacket,
            ClientboundSetHealthPacket, ClientboundSetPlayerInventoryPacket,
            ClientboundSoundPacket, ClientboundSystemChatPacket,
            ServerboundChunkBatchReceivedPacket,
        };
        let packet_payload = payload;
        let mut buffer = el_protocol::PacketBuffer::from_bytes(packet_payload.clone());
        if packet_id == 44 {
            if let Ok(keep_alive_id) = buffer.read_i64() {
                if DEBUG_VERBOSE_NETWORK {
                    println!("[Network] Responding to Play KeepAlive: {}", keep_alive_id);
                }
                let mut response = el_protocol::PacketBuffer::new();
                response.write_var_i32(28);
                let _ = response.write_i64(keep_alive_id);
                if let Some(conn) = self.session.connection.as_mut() {
                    let _ = conn.send_raw_payload(&response.into_inner());
                }
            }
        } else if packet_id == ClientboundAddEntityPacket::ID {
            if let Ok(packet) = ClientboundAddEntityPacket::decode(&mut buffer) {
                let entity_types = BuiltInRegistries::entity_types();
                let kind = if packet.entity_type >= 0
                    && (packet.entity_type as usize) < entity_types.size()
                {
                    entity_types
                        .get_by_id(packet.entity_type as usize)
                        .location
                        .to_string()
                } else {
                    format!("minecraft:entity_{}", packet.entity_type)
                };
                let yaw_degrees = (packet.yaw as f32) * 360.0 / 256.0;
                let pitch_degrees = (packet.pitch as f32) * 360.0 / 256.0;
                let head_yaw_degrees = (packet.head_yaw as f32) * 360.0 / 256.0;
                let velocity_x = packet.xa as f64 / 8000.0;
                let velocity_y = packet.ya as f64 / 8000.0;
                let velocity_z = packet.za as f64 / 8000.0;
                self.handle_remote_network_event(
                    el_protocol_backend::BackendNetworkEvent::EntityAdded {
                        entity: el_protocol_backend::BackendRemoteEntityEvent {
                            id: packet.id,
                            uuid: packet.uuid,
                            kind,
                            x: packet.x,
                            y: packet.y,
                            z: packet.z,
                            yaw_degrees,
                            pitch_degrees,
                            head_yaw_degrees,
                            spawn_data: packet.data,
                            falling_block_state_id: None,
                            velocity_x,
                            velocity_y,
                            velocity_z,
                        },
                    },
                );
            }
        } else if packet_id == ClientboundLoginPacket::ID {
            match ClientboundLoginPacket::decode(&mut buffer) {
                Ok(packet) => {
                    if DEBUG_VERBOSE_NETWORK {
                        println!(
                            "[Network] Logged in! Player ID: {}, GameMode: {:?}, SeaLevel: {}",
                            packet.player_id,
                            packet.spawn_info.game_type,
                            packet.spawn_info.sea_level
                        );
                    }
                    let id = packet.spawn_info.game_type as i32;
                    self.reset_player_inventory_menu_state();
                    self.session
                        .game_mode
                        .set_local_mode(crate::gameplay::game_mode::GameType::by_id(id));
                    self.session.reconcile_player_flying_from_game_mode(false);
                    self.session.remote_show_death_screen = packet.show_death_screen;
                    self.session.remote_level_hardcore = packet.hardcore;
                    self.session.remote_respawn_request_sent = false;
                    match self.create_client_level() {
                        Ok(level) => {
                            self.session.level = Some(level);
                            self.multiplayer_world_ready = false;
                            self.set_multiplayer_chunk_loading_started(false);
                            self.session.player_loaded_sent = false;
                            self.needs_mesh_rebuild = false;
                        }
                        Err(err) => {
                            log::error!(
                                "[Network] Failed to create client level for multiplayer session: {err:#?}"
                            );
                        }
                    }
                    if let Some(conn) = self.session.connection.as_mut() {
                        let _ = conn.send_packet(
                            &el_protocol::packets::common::ServerboundClientInformationPacket {
                                language: self.gui_manager.client_information_language().to_owned(),
                                view_distance: 12,
                                chat_visibility: 0,
                                chat_colors: true,
                                model_customization: 127,
                                main_hand: 1,
                                text_filtering_enabled: true,
                                allows_listing: self
                                    .gui_manager
                                    .client_information_allows_listing(),
                                particle_status: 0,
                            },
                        );
                    }
                }
                Err(e) => {
                    log::error!("[Network] Failed to decode ClientboundLoginPacket: {e:?}");
                }
            }
        } else if packet_id == ClientboundDisconnectPacket::ID {
            if let Ok(packet) = ClientboundDisconnectPacket::decode(&mut buffer) {
                log::error!("[Network] Server disconnected: {}", packet.reason);
                self.handle_remote_network_event(
                    el_protocol_backend::BackendNetworkEvent::Disconnected {
                        reason: packet.reason,
                    },
                );
                self.session.connection = None;
            }
        } else if packet_id == ClientboundLevelChunkWithLightPacket::ID {
            match ClientboundLevelChunkWithLightPacket::decode(&mut buffer) {
                Ok(packet) => {
                    if DEBUG_VERBOSE_NETWORK {
                        println!(
                            "[ChunkDecode] el_protocol decoded chunk [{}, {}]: section_data len = {}",
                            packet.x,
                            packet.z,
                            packet.chunk_data.section_data.len()
                        );
                    }
                    if self.session.level.is_none() {
                        match self.create_client_level() {
                            Ok(level) => {
                                self.session.level = Some(level);
                            }
                            Err(err) => {
                                log::error!(
                                    "[Network] Failed to create client level before loading chunk [{}, {}]: {err:#?}",
                                    packet.x,
                                    packet.z
                                );
                            }
                        }
                    }
                    let decoded = crate::network::multiplayer::chunk_decoder::decode_chunk_sections(
                        packet.x,
                        packet.z,
                        -4,
                        19,
                        &packet.chunk_data.section_data,
                    );
                    match decoded {
                        Ok(mut chunk) => {
                            crate::network::multiplayer::chunk_decoder::install_block_entities(
                                &mut chunk,
                                packet.x,
                                packet.z,
                                &packet.chunk_data.block_entities,
                            );
                            crate::network::multiplayer::chunk_decoder::apply_light_data(
                                &mut chunk,
                                &packet.light_data,
                            );
                            let non_air_blocks = chunk.non_air_block_count();
                            let chunk_pos = ChunkPos::new(packet.x, packet.z);
                            let moving_piston_entries = moving_piston_entities_from_chunk(&chunk);
                            self.set_multiplayer_chunk_loading_started(true);
                            self.block_entity_lids
                                .retain(|pos, _| ChunkPos::from_block(*pos) != chunk_pos);
                            self.decorated_pot_wobbles
                                .retain(|pos, _| ChunkPos::from_block(*pos) != chunk_pos);
                            self.replace_moving_pistons_for_chunk(chunk_pos, moving_piston_entries);
                            self.install_chunk_sign_texts(chunk_pos, &chunk);
                            if let Some(level) = &mut self.session.level {
                                level.load_chunk(chunk);
                                self.multiplayer_world_ready = true;
                                if DEBUG_VERBOSE_NETWORK {
                                    println!(
                                        "[Network] Loaded chunk [{}, {}] (non_air_blocks={}); total loaded chunks = {}",
                                        packet.x,
                                        packet.z,
                                        non_air_blocks,
                                        level.loaded_chunk_count()
                                    );
                                }
                                self.needs_mesh_rebuild = true;
                                self.renderer.block_entity_mesh_dirty = true;
                            }
                        }
                        Err(error) => {
                            log::error!(
                                "[ChunkDecode] failed to decode sections for chunk [{}, {}]: {error:?}",
                                packet.x,
                                packet.z
                            );
                        }
                    }
                }
                Err(e) => {
                    log::error!("Failed to decode chunk packet with el_protocol: {e:#?}");
                }
            }
        } else if packet_id == ClientboundSystemChatPacket::ID {
            if let Ok(packet) = ClientboundSystemChatPacket::decode(&mut buffer) {
                if !packet.content.is_empty() {
                    if packet.overlay {
                        self.gui_manager.hud.set_overlay_message(packet.content);
                    } else {
                        self.gui_manager.add_server_system_chat(packet.content);
                    }
                }
            }
        } else if packet_id == ClientboundSetHealthPacket::ID {
            if let Ok(packet) = ClientboundSetHealthPacket::decode(&mut buffer) {
                self.session.player.hurt_to(packet.health);
                self.session.player.food = packet.food;
                self.session.player.food_saturation = packet.saturation;
                if packet.health > 0.0 {
                    self.session.remote_respawn_request_sent = false;
                }
            }
        } else if packet_id == ClientboundSetExperiencePacket::ID {
            if let Ok(packet) = ClientboundSetExperiencePacket::decode(&mut buffer) {
                self.session.player.xp_level = packet.experience_level;
                self.session.player.xp_progress = packet.experience_progress;
            }
        } else if packet_id == ClientboundGameEventPacket::ID {
            if let Ok(packet) = ClientboundGameEventPacket::decode(&mut buffer) {
                if DEBUG_VERBOSE_NETWORK {
                    println!(
                        "[Network] GameEvent packet: event_id={}, value={}",
                        packet.event_id, packet.value
                    );
                }
                self.handle_clientbound_game_event_like_java(packet.event_id, packet.value);
            }
        } else if packet_id == ClientboundChangeDifficultyPacket::ID {
            if let Ok(packet) = ClientboundChangeDifficultyPacket::decode(&mut buffer) {
                self.gui_manager
                    .hud
                    .chat_messages
                    .push(format!("Difficulty set to {}", packet.difficulty));
            }
        } else if packet_id == ClientboundRespawnPacket::ID {
            if let Ok(packet) = ClientboundRespawnPacket::decode(&mut buffer) {
                self.gui_manager.close_death_screen_after_respawn();
                #[cfg(feature = "shaderpacks")]
                self.invalidate_shader_history();
                let keeps_entity_data = (packet.data_to_keep & 2) != 0;
                let game_type = GameType::from(packet.spawn_info.game_type);
                let previous_game_type = packet.spawn_info.previous_game_type.map(GameType::from);
                self.session.player.food = 20;
                self.session.player.food_saturation = 5.0;
                self.session.player.inventory =
                    (0..46).map(|_| el_core::item::ItemStack::empty()).collect();
                self.reset_player_inventory_menu_state();
                self.clear_local_item_use();
                self.reset_local_player_for_respawn_like_java(keeps_entity_data);
                self.session.local_move_send_state = VanillaMoveSendState::default();
                self.session.player.reset_death_time();
                if !keeps_entity_data {
                    self.apply_no_keep_respawn_kinematics_like_java();
                }
                self.session.player.reset_lerped_head_rotation();
                if (packet.data_to_keep & 1) == 0 {
                    self.session.player.attributes.clear_all_modifiers();
                }
                self.reset_respawn_abilities_like_new_local_player();
                self.apply_respawn_game_mode_like_java(game_type, Some(previous_game_type));
                self.session.player.active_effects.clear();
                self.session.player_loaded_sent = false;
                self.multiplayer_world_ready = false;
                self.set_multiplayer_chunk_loading_started(false);
            }
        } else if packet_id == ClientboundPlayerPositionPacket::ID {
            if let Ok(packet) = ClientboundPlayerPositionPacket::decode(&mut buffer) {
                #[cfg(feature = "shaderpacks")]
                self.invalidate_shader_history();
                let mut x = packet.change.position.x;
                let mut y = packet.change.position.y;
                let mut z = packet.change.position.z;
                let mut yaw_degrees = packet.change.y_rot;
                let mut pitch_degrees = packet.change.x_rot;
                let current_pos = self.session.player.exact_position();
                let current_old_pos = self.session.player.exact_old_position();
                let current_velocity = self.session.player.exact_velocity();
                let current_yaw_degrees = self.session.player.y_rot_degrees();
                let current_pitch_degrees = self.session.player.x_rot_degrees();
                let current_old_yaw_degrees = self.session.player.old_y_rot_degrees();
                let current_old_pitch_degrees = self.session.player.old_x_rot_degrees();
                let has_relative = |relative| {
                    packet
                        .relatives
                        .iter()
                        .any(|&candidate| candidate == relative)
                };
                let old_pos = glam::DVec3::new(
                    if has_relative(el_protocol::packets::game::Relative::X) {
                        current_old_pos.x + packet.change.position.x
                    } else {
                        packet.change.position.x
                    },
                    if has_relative(el_protocol::packets::game::Relative::Y) {
                        current_old_pos.y + packet.change.position.y
                    } else {
                        packet.change.position.y
                    },
                    if has_relative(el_protocol::packets::game::Relative::Z) {
                        current_old_pos.z + packet.change.position.z
                    } else {
                        packet.change.position.z
                    },
                );
                let old_yaw_degrees = if has_relative(el_protocol::packets::game::Relative::YRot) {
                    current_old_yaw_degrees + packet.change.y_rot
                } else {
                    packet.change.y_rot
                };
                let old_pitch_degrees =
                    (if has_relative(el_protocol::packets::game::Relative::XRot) {
                        current_old_pitch_degrees + packet.change.x_rot
                    } else {
                        packet.change.x_rot
                    })
                    .clamp(-90.0, 90.0);
                for relative in &packet.relatives {
                    match relative {
                        el_protocol::packets::game::Relative::X => x += current_pos.x,
                        el_protocol::packets::game::Relative::Y => y += current_pos.y,
                        el_protocol::packets::game::Relative::Z => z += current_pos.z,
                        el_protocol::packets::game::Relative::YRot => {
                            yaw_degrees += current_yaw_degrees;
                        }
                        el_protocol::packets::game::Relative::XRot => {
                            pitch_degrees += current_pitch_degrees;
                        }
                        _ => {}
                    }
                }
                let server_spawn = glam::DVec3::new(x, y, z);
                let server_yaw_degrees = yaw_degrees;
                let server_pitch_degrees = pitch_degrees.clamp(-90.0, 90.0);
                let server_velocity = Self::absolute_delta_from_protocol_relatives(
                    current_velocity,
                    glam::DVec3::new(
                        packet.change.delta_movement.x,
                        packet.change.delta_movement.y,
                        packet.change.delta_movement.z,
                    ),
                    current_yaw_degrees,
                    current_pitch_degrees,
                    server_yaw_degrees,
                    server_pitch_degrees,
                    &packet.relatives,
                );
                if LocalPlayer::slide_probe_enabled() {
                    let position_diff = glam::DVec3::new(
                        server_spawn.x - current_pos.x,
                        server_spawn.y - current_pos.y,
                        server_spawn.z - current_pos.z,
                    );
                    let position_diff_length = position_diff.length();
                    LocalPlayer::slide_probe_log(format!(
                        "[SlideProbe][Rust][server_position] id={} pos=[{:.12},{:.12},{:.12}] delta_velocity=[{:.12},{:.12},{:.12}] yaw={:.6} pitch={:.6} relatives={:?} before=[{:.12},{:.12},{:.12}] abs_velocity=[{:.12},{:.12},{:.12}] diff=[{:.12},{:.12},{:.12}] diff_length={:.12}",
                        packet.id,
                        server_spawn.x,
                        server_spawn.y,
                        server_spawn.z,
                        packet.change.delta_movement.x,
                        packet.change.delta_movement.y,
                        packet.change.delta_movement.z,
                        server_yaw_degrees,
                        server_pitch_degrees,
                        packet.relatives,
                        current_pos.x,
                        current_pos.y,
                        current_pos.z,
                        server_velocity.x,
                        server_velocity.y,
                        server_velocity.z,
                        position_diff.x,
                        position_diff.y,
                        position_diff.z,
                        position_diff_length,
                    ));
                }
                let is_passenger = self.session.player.is_passenger
                    || self.session.remote_vehicle_entity_id.is_some();
                if !is_passenger {
                    self.session
                        .player
                        .set_position_with_old_position_d(server_spawn, old_pos);
                    self.session.player.set_velocity_d(server_velocity);
                    self.session
                        .player
                        .set_rotation_degrees_like_java(server_yaw_degrees, server_pitch_degrees);
                    self.session
                        .player
                        .set_old_rotation_degrees_raw_like_java(old_yaw_degrees, old_pitch_degrees);
                }
                self.pending_server_spawn = None;
                if let Some(conn) = self.session.connection.as_mut() {
                    let _ = conn.send_packet(
                        &el_protocol::packets::game::ServerboundAcceptTeleportationPacket {
                            id: packet.id,
                        },
                    );
                    let confirm_pos = if is_passenger {
                        current_pos
                    } else {
                        server_spawn
                    };
                    let confirm_yaw = if is_passenger {
                        current_yaw_degrees
                    } else {
                        self.session.player.y_rot_degrees()
                    };
                    let confirm_pitch = if is_passenger {
                        current_pitch_degrees.clamp(-90.0, 90.0)
                    } else {
                        self.session.player.x_rot_degrees()
                    };
                    let _ = conn.send_packet(
                        &el_protocol::packets::game::ServerboundMovePlayerPosRotPacket {
                            x: confirm_pos.x,
                            y: confirm_pos.y,
                            z: confirm_pos.z,
                            y_rot: confirm_yaw,
                            x_rot: confirm_pitch,
                            on_ground: false,
                            horizontal_collision: false,
                        },
                    );
                }
            }
        } else if packet_id == ClientboundPlayerRotationPacket::ID {
            if let Ok(packet) = ClientboundPlayerRotationPacket::decode(&mut buffer) {
                let yaw_degrees = if packet.relative_y {
                    self.session.player.y_rot_degrees() + packet.y_rot
                } else {
                    packet.y_rot
                };
                let pitch_degrees = (if packet.relative_x {
                    self.session.player.x_rot_degrees() + packet.x_rot
                } else {
                    packet.x_rot
                })
                .clamp(-90.0, 90.0);
                self.session
                    .player
                    .set_rotation_degrees_like_java(yaw_degrees, pitch_degrees);
                self.session.player.copy_current_rotation_to_old_like_java();
                if let Some(conn) = self.session.connection.as_mut() {
                    let _ = conn.send_packet(
                        &el_protocol::packets::game::ServerboundMovePlayerRotPacket {
                            y_rot: self.session.player.y_rot_degrees(),
                            x_rot: self.session.player.x_rot_degrees(),
                            on_ground: false,
                            horizontal_collision: false,
                        },
                    );
                }
            }
        } else if packet_id == ClientboundSetPlayerInventoryPacket::ID {
            if let Ok(packet) = ClientboundSetPlayerInventoryPacket::decode(&mut buffer) {
                self.set_player_inventory_slot(packet.slot as usize, packet.contents);
            }
        } else if packet_id == ClientboundContainerSetContentPacket::ID {
            if let Ok(packet) = ClientboundContainerSetContentPacket::decode(&mut buffer) {
                if packet.container_id == 0 {
                    self.session.player_inventory_state_id = packet.state_id;
                    self.session.player_inventory_carried_item = packet.carried_item.clone();
                }
                let mut player_slots_to_update = Vec::new();
                let mut screen_updated = false;
                if let Some(crate::ui::gui::ActiveScreen::Container(screen)) =
                    self.gui_manager.active_screen_mut()
                {
                    if screen.container_id == packet.container_id {
                        screen.state_id = packet.state_id;
                        screen.carried_item = packet.carried_item.clone();
                        if screen.menu_type == el_inventory::menu::MenuType::Creative {
                            for (menu_slot, stack) in packet.items.clone().into_iter().enumerate() {
                                if let Some(player_slot) =
                                    Self::inventory_menu_slot_to_player_slot(menu_slot)
                                {
                                    player_slots_to_update.push((player_slot, stack));
                                }
                            }
                            screen_updated = true;
                        } else {
                            for (menu_slot, stack) in packet.items.clone().into_iter().enumerate() {
                                screen.menu.set_slot_item(menu_slot, stack.clone());
                                if menu_slot < screen.menu.slots.len() {
                                    let slot = &screen.menu.slots[menu_slot];
                                    if slot.container_idx == 0 {
                                        player_slots_to_update.push((slot.slot_idx, stack));
                                    }
                                }
                            }
                            screen_updated = true;
                        }
                    }
                }
                if screen_updated {
                    for (player_slot, stack) in player_slots_to_update {
                        self.set_player_inventory_slot(player_slot, stack);
                    }
                    if let Some(crate::ui::gui::ActiveScreen::Container(screen)) =
                        self.gui_manager.active_screen_mut()
                    {
                        if screen.menu_type == el_inventory::menu::MenuType::Creative {
                            for i in 0..9 {
                                screen.menu.set_slot_item(
                                    45 + i,
                                    self.session.player.inventory[i].clone(),
                                );
                            }
                        }
                    }
                } else if packet.container_id == 0 {
                    for (menu_slot, stack) in packet.items.into_iter().enumerate() {
                        if let Some(player_slot) =
                            Self::inventory_menu_slot_to_player_slot(menu_slot)
                        {
                            self.set_player_inventory_slot(player_slot, stack);
                        }
                    }
                }
            }
        } else if packet_id == ClientboundContainerSetSlotPacket::ID {
            if let Ok(packet) = ClientboundContainerSetSlotPacket::decode(&mut buffer) {
                if packet.container_id == 0 {
                    self.session.player_inventory_state_id = packet.state_id;
                }
                let mut player_slot_to_update = None;
                let mut screen_updated = false;
                if let Some(crate::ui::gui::ActiveScreen::Container(screen)) =
                    self.gui_manager.active_screen_mut()
                {
                    if screen.container_id == packet.container_id {
                        screen.state_id = packet.state_id;
                        let menu_slot = packet.slot as usize;
                        if screen.menu_type == el_inventory::menu::MenuType::Creative {
                            if let Some(player_slot) =
                                Self::inventory_menu_slot_to_player_slot(menu_slot)
                            {
                                player_slot_to_update =
                                    Some((player_slot, packet.item_stack.clone()));
                            }
                            screen_updated = true;
                        } else {
                            screen
                                .menu
                                .set_slot_item(menu_slot, packet.item_stack.clone());
                            if menu_slot < screen.menu.slots.len() {
                                let slot = &screen.menu.slots[menu_slot];
                                if slot.container_idx == 0 {
                                    player_slot_to_update =
                                        Some((slot.slot_idx, packet.item_stack.clone()));
                                }
                            }
                            screen_updated = true;
                        }
                    }
                }
                if screen_updated {
                    if let Some((player_slot, stack)) = player_slot_to_update {
                        self.set_player_inventory_slot(player_slot, stack);
                    }
                    if let Some(crate::ui::gui::ActiveScreen::Container(screen)) =
                        self.gui_manager.active_screen_mut()
                    {
                        if screen.menu_type == el_inventory::menu::MenuType::Creative {
                            for i in 0..9 {
                                screen.menu.set_slot_item(
                                    45 + i,
                                    self.session.player.inventory[i].clone(),
                                );
                            }
                        }
                    }
                } else if packet.container_id == 0 {
                    if let Some(player_slot) =
                        Self::inventory_menu_slot_to_player_slot(packet.slot as usize)
                    {
                        self.set_player_inventory_slot(player_slot, packet.item_stack);
                    }
                }
            }
        } else if packet_id == ClientboundSetCursorItemPacket::ID {
            if let Ok(packet) = ClientboundSetCursorItemPacket::decode(&mut buffer) {
                self.apply_remote_cursor_item(packet.contents);
            }
        } else if packet_id == ClientboundContainerClosePacket::ID {
            if let Ok(packet) = ClientboundContainerClosePacket::decode(&mut buffer) {
                if self.gui_manager.active_container_id() == Some(packet.container_id) {
                    self.gui_manager.close_screen();
                }
            }
        } else if packet_id == ClientboundOpenScreenPacket::ID {
            if let Ok(packet) = ClientboundOpenScreenPacket::decode(&mut buffer) {
                let menu_type = u32::try_from(packet.menu_type)
                    .map(Self::menu_type_from_protocol_id)
                    .unwrap_or(el_inventory::menu::MenuType::Chest3Rows);
                let mut player_inv =
                    el_inventory::container::SimpleContainer::new_player_inventory(46);
                for i in 0..46.min(self.session.player.inventory.len()) {
                    player_inv.set_item(i, self.session.player.inventory[i].clone());
                }
                self.gui_manager.open_container(
                    packet.container_id,
                    menu_type,
                    packet.title,
                    player_inv,
                    0,
                );
                self.finish_server_driven_screen_open();
            }
        } else if packet_id == ClientboundContainerSetDataPacket::ID {
            let _ = ClientboundContainerSetDataPacket::decode(&mut buffer);
        } else if packet_id == ClientboundBlockUpdatePacket::ID {
            if let Ok(packet) = ClientboundBlockUpdatePacket::decode(&mut buffer) {
                if let Ok(state_id) = usize::try_from(packet.block_state_id) {
                    self.apply_remote_block_update(BlockUpdateEvent {
                        x: packet.pos.x,
                        y: packet.pos.y,
                        z: packet.pos.z,
                        state_id,
                    });
                }
            }
        } else if packet_id == ClientboundSectionBlocksUpdatePacket::ID {
            if let Ok(packet) = ClientboundSectionBlocksUpdatePacket::decode(&mut buffer) {
                let mut invalidations = RemoteSectionMeshInvalidationBatch::default();
                for update in packet.updates {
                    if let Ok(state_id) = usize::try_from(update.block_state_id) {
                        self.apply_remote_block_update_with_deferred_mesh_invalidations(
                            BlockUpdateEvent {
                                x: update.pos.x,
                                y: update.pos.y,
                                z: update.pos.z,
                                state_id,
                            },
                            Some(&mut invalidations),
                        );
                    }
                }
                self.flush_remote_section_mesh_invalidations(invalidations);
            }
        } else if packet_id == ClientboundBlockEntityDataPacket::ID {
            if let Ok(packet) = ClientboundBlockEntityDataPacket::decode(&mut buffer) {
                let pos = BlockPos::new(packet.pos.x, packet.pos.y, packet.pos.z);
                let block_entity_exists = self.session.level.as_ref().is_some_and(|level| {
                    level
                        .chunks
                        .get(&ChunkPos::from_block(pos))
                        .is_some_and(|chunk| chunk.block_entities.contains_key(&pos))
                });
                if !block_entity_exists {
                    return;
                }
                let kind = self
                    .session
                    .level
                    .as_ref()
                    .map(|level| level.get_block_state(pos).block.to_string())
                    .unwrap_or_else(|| {
                        format!("block_entity_registry_id:{}", packet.block_entity_type_id)
                    });
                let mut nbt = vec![packet.tag.get_id()];
                if el_nbt::io::write_payload(&mut nbt, &packet.tag).is_ok() {
                    self.handle_remote_network_event(
                        el_protocol_backend::BackendNetworkEvent::BlockEntityUpdate {
                            pos: el_protocol_backend::BackendBlockPos {
                                x: pos.x,
                                y: pos.y,
                                z: pos.z,
                            },
                            data: el_protocol_backend::BackendBlockEntityData { kind, nbt },
                        },
                    );
                }
            }
        } else if packet_id == ClientboundBlockEventPacket::ID {
            if let Ok(packet) = ClientboundBlockEventPacket::decode(&mut buffer) {
                self.handle_native_block_event(&packet);
            }
        } else if packet_id == ClientboundLevelEventPacket::ID {
            if let Ok(packet) = ClientboundLevelEventPacket::decode(&mut buffer) {
                self.handle_level_event_sound(
                    packet.type_ as u32,
                    el_math::block_pos::BlockPos {
                        x: packet.pos.x,
                        y: packet.pos.y,
                        z: packet.pos.z,
                    },
                    packet.data as u32,
                    packet.global_event,
                );
                self.handle_level_event_particles(
                    packet.type_ as u32,
                    el_math::block_pos::BlockPos {
                        x: packet.pos.x,
                        y: packet.pos.y,
                        z: packet.pos.z,
                    },
                    packet.data as u32,
                );
            }
        } else if packet_id == ClientboundSoundPacket::ID {
            match ClientboundSoundPacket::decode(&mut buffer) {
                Ok(packet) => self.handle_native_sound(packet),
                Err(el_protocol::BufferError::InvalidEnumId {
                    name: "SoundEvent holder",
                    id,
                }) => {
                    if DEBUG_VERBOSE_NETWORK {
                        println!(
                            "[Network] Skipping sound with unresolvable registry holder id {id}"
                        );
                    }
                }
                Err(err) => {
                    log::error!("Failed to decode ClientboundSoundPacket: {err:#?}");
                }
            }
        } else if packet_id == ClientboundChunkBatchStartPacket::ID {
            if ClientboundChunkBatchStartPacket::decode(&mut buffer).is_ok() {
                if DEBUG_VERBOSE_NETWORK {
                    println!("[Network] Chunk batch start received");
                }
            }
        } else if packet_id == ClientboundChunkBatchFinishedPacket::ID {
            if let Ok(packet) = ClientboundChunkBatchFinishedPacket::decode(&mut buffer) {
                if DEBUG_VERBOSE_NETWORK {
                    println!(
                        "[Network] Chunk batch finished: batch_size={}",
                        packet.batch_size
                    );
                }
                if let Some(conn) = self.session.connection.as_mut() {
                    let _ = conn.send_packet(&ServerboundChunkBatchReceivedPacket {
                        desired_chunks_per_tick: 10.0,
                    });
                }
            }
        } else {
            let remaining_payload = buffer.read_bytes(buffer.remaining()).unwrap_or_default();
            let packet_name = if packet_id >= 0 {
                format!("clientbound_play_packet_{packet_id}")
            } else {
                format!("invalid_negative_packet_{packet_id}")
            };
            if DEBUG_VERBOSE_NETWORK {
                println!(
                    "[Network] Ignoring unhandled Play packet ID {} / {} ({} bytes)",
                    packet_id,
                    packet_name,
                    remaining_payload.len()
                );
            }
        }
    }
    fn maybe_rebuild_world_mesh(&mut self) {
        if self.session.remote_connection.is_some() {
            return;
        }
        if !self.gui_manager.is_active_screen_in_world() {
            return;
        }
        if !self.needs_mesh_rebuild {
            return;
        }
        if self.mesh_rebuild_wait_frames > 0 {
            self.mesh_rebuild_wait_frames -= 1;
            return;
        }
        self.rebuild_world_mesh();
        self.needs_mesh_rebuild = false;
        self.mesh_rebuild_wait_frames = 0;
    }
    pub fn schedule_world_mesh_rebuild(&mut self) {
        self.clear_local_mesh_cache();
        self.needs_mesh_rebuild = true;
        self.mesh_rebuild_wait_frames = 0;
    }
    fn maybe_send_player_loaded(&mut self) {
        if self.session.remote_connection.is_some() {
            if self.session.player_loaded_sent {
                return;
            }
            self.tick_remote_level_load_tracker_like_java();
            if self.remote_level_load_phase != RemoteLevelLoadPhase::ClientLevelReady {
                return;
            }
            let Some(packet_tx) = self
                .session
                .remote_connection
                .as_ref()
                .map(|connection| connection.packet_tx.clone())
            else {
                return;
            };
            if LocalPlayer::slide_probe_enabled() {
                let player_section = RenderSectionKey::from_block_pos(
                    level_load_player_block_position_like_java(self.session.player.position),
                );
                let camera_section = RenderSectionKey::from_block_pos(self.camera.block_position());
                LocalPlayer::slide_probe_log(format!(
                    "[LoadDebug][Rust][player_loaded] decision=send phase=ClientLevelReady player_section=[{}, {}, {}] camera_section=[{}, {}, {}] camera_compiled={} section_ready={} loaded_chunks={}",
                    player_section.chunk_x,
                    player_section.section_y,
                    player_section.chunk_z,
                    camera_section.chunk_x,
                    camera_section.section_y,
                    camera_section.chunk_z,
                    level_load_camera_section_is_compiled_and_visible_like_java(
                        camera_section,
                        &self.renderer.remote_compiled_sections,
                    ),
                    self.remote_level_load_section_ready,
                    self.session
                        .level
                        .as_ref()
                        .map_or(0, |level| level.loaded_chunk_count()),
                ));
            }
            println!(
                "[Network] Sending Azalea ServerboundPlayerLoaded to server! phase=ClientLevelReady loaded_chunks={}",
                self.session
                    .level
                    .as_ref()
                    .map_or(0, |level| level.loaded_chunk_count())
            );
            packet_tx.send_player_loaded();
            self.session.player_loaded_sent = true;
            return;
        }
        if self.session.player_loaded_sent
            || !self.multiplayer_chunk_loading_started
            || !self.multiplayer_world_ready
            || self
                .session
                .level
                .as_ref()
                .map(|level| level.loaded_chunk_count() == 0)
                .unwrap_or(true)
        {
            return;
        }
        if let Some(conn) = self.session.connection.as_mut() {
            println!(
                "[Network] Sending ServerboundPlayerLoadedPacket to server! loaded_chunks={} remote=false",
                self.session
                    .level
                    .as_ref()
                    .map_or(0, |level| level.loaded_chunk_count())
            );
            let _ = conn.send_packet(&el_protocol::packets::game::ServerboundPlayerLoadedPacket);
            self.session.player_loaded_sent = true;
        }
    }
    fn inventory_menu_slot_to_player_slot(slot: usize) -> Option<usize> {
        crate::gameplay::session::inventory::inventory_menu_slot_to_player_slot(slot)
    }
    fn reset_player_inventory_menu_state(&mut self) {
        self.session.player_inventory_state_id = 0;
        self.session.player_inventory_carried_item = el_core::item::ItemStack::empty();
    }
    fn apply_local_player_after_hard_vehicle_snap(&mut self, vehicle_id: i32) {
        crate::gameplay::session::vehicle::apply_local_player_after_hard_vehicle_snap(
            &mut self.session,
            vehicle_id,
        );
    }
    fn set_player_inventory_slot(&mut self, slot: usize, stack: el_core::ItemStack) {
        let menu = Self::inventory_menu_context(&self.gui_manager);
        let effects = self.session.set_inventory_player_slot(slot, stack, menu);
        self.apply_inventory_ui_effects(effects);
    }
    pub fn process_mouse_motion(&mut self, dx: f64, dy: f64) {
        if self.content_screen_active() {
            return;
        }
        #[cfg(target_arch = "wasm32")]
        let window_active = self.window.has_focus()
            || matches!(
                self.current_cursor_grab_mode.get(),
                Some(
                    winit::window::CursorGrabMode::Locked | winit::window::CursorGrabMode::Confined
                )
            )
            || self.manual_cursor_grab.get();
        #[cfg(not(target_arch = "wasm32"))]
        let window_active = self.window.has_focus();
        if !window_active {
            return;
        }
        self.mouse_handler.accumulate_relative_motion(dx, dy, true);
    }
    fn apply_pending_mouse_motion(&mut self) {
        let now = Instant::now();
        let elapsed_seconds = now
            .saturating_duration_since(self.last_mouse_motion_apply_at)
            .as_secs_f64();
        self.last_mouse_motion_apply_at = now;
        #[cfg(target_arch = "wasm32")]
        let window_active = self.window.has_focus()
            || matches!(
                self.current_cursor_grab_mode.get(),
                Some(
                    winit::window::CursorGrabMode::Locked | winit::window::CursorGrabMode::Confined
                )
            )
            || self.manual_cursor_grab.get();
        #[cfg(not(target_arch = "wasm32"))]
        let window_active = self.window.has_focus();
        if self.content_screen_active() || !window_active {
            self.mouse_handler.discard_accumulated_motion();
            return;
        }
        let mouse_turn = self.mouse_handler.handle_accumulated_movement(
            elapsed_seconds,
            MouseTurnOptions {
                sensitivity: self.gui_manager.sensitivity_setting,
                invert_x: self.gui_manager.invert_mouse_x,
                invert_y: self.gui_manager.invert_mouse_y,
                smooth_camera: self.gui_manager.smooth_camera,
                first_person: self.camera_type.is_first_person(),
                scoping: self.player_is_scoping(),
            },
        );
        let Some(mouse_turn) = mouse_turn else {
            return;
        };
        if self.session.level.is_none() {
            self.camera.sensitivity = self.gui_manager.sensitivity_setting;
            self.camera.yaw += mouse_turn.yaw_delta;
            self.camera.pitch += mouse_turn.pitch_delta;
            const SAFE_FRAC_PI_2: f32 = std::f32::consts::FRAC_PI_2 - 0.0001;
            self.camera.pitch = self.camera.pitch.clamp(-SAFE_FRAC_PI_2, SAFE_FRAC_PI_2);
            if self.manual_cursor_grab.get() {
                self.center_cursor_in_window();
            }
            return;
        }
        MouseHandler::turn_player(&mut self.session.player, mouse_turn);
        let boat_yaw_degrees = self
            .session
            .remote_vehicle_entity_id
            .and_then(|vehicle_id| {
                self.session
                    .remote_entities
                    .get(&vehicle_id)
                    .filter(|vehicle| is_remote_abstract_boat(&vehicle.kind))
                    .map(RemoteEntityRenderState::y_rot_degrees)
            });
        if let Some(boat_yaw_degrees) = boat_yaw_degrees {
            self.session
                .player
                .clamp_rotation_to_abstract_boat_degrees(boat_yaw_degrees);
        }
        if self.manual_cursor_grab.get() {
            self.center_cursor_in_window();
        }
    }
    pub fn finish_input_frame(&mut self) {}
    pub fn take_requested_quit(&mut self) -> bool {
        self.gui_manager.take_requested_quit()
    }
    pub fn apply_pending_window_settings(&mut self) {
        self.apply_pending_window_fullscreen();
        self.apply_pending_font_settings();
    }
    fn apply_pending_font_settings(&mut self) {
        if !self.gui_manager.take_font_reload_request() {
            return;
        }
        if let Err(error) = self.gui_manager.reload_font(
            &self.device,
            &self.queue,
            &self.renderer.texture_bind_group_layout,
        ) {
            log::error!("Font options reload failed; keeping the previous font: {error}");
            return;
        }
        self.renderer.sign_text_mesh_cache.borrow_mut().clear();
        self.renderer.name_tag_layout_cache.borrow_mut().clear();
    }
    fn apply_pending_window_fullscreen(&mut self) {
        let fullscreen_request = self.gui_manager.take_window_fullscreen_request();
        let mode_changed = self.gui_manager.take_window_video_mode_change_request();
        if fullscreen_request.is_none() && !mode_changed {
            return;
        }
        let enabled = fullscreen_request.unwrap_or_else(|| self.window.fullscreen().is_some());
        if self.window.fullscreen().is_some() != enabled || (enabled && mode_changed) {
            self.set_window_fullscreen(enabled);
        }
        if fullscreen_request.is_some() {
            self.gui_manager.sync_fullscreen_option_from_window(enabled);
        }
        self.update_cursor_grab();
    }
    fn handle_global_key_press(&mut self, event: &WindowEvent) -> bool {
        let Some(key_code) = Self::pressed_key(event) else {
            return false;
        };
        if self.session.controls.matches_input(
            KeyAction::Fullscreen,
            crate::input::BoundInput::Key(key_code),
        ) {
            self.toggle_fullscreen();
            return true;
        }
        if self.session.controls.matches_input(
            KeyAction::Screenshot,
            crate::input::BoundInput::Key(key_code),
        ) {
            self.screenshot_requested = true;
            return true;
        }
        false
    }
    fn handle_debug_modifier_key(&mut self, event: &WindowEvent) -> bool {
        if !self.session.controls.is_down(KeyAction::DebugModifier) {
            return false;
        }
        let Some(key_code) = Self::pressed_key(event) else {
            return false;
        };
        if key_code == KeyCode::F3 {
            return false;
        }
        let input = crate::input::BoundInput::Key(key_code);
        for action in [
            KeyAction::DebugCrash,
            KeyAction::DebugReloadChunk,
            KeyAction::DebugShowHitboxes,
            KeyAction::DebugClearChat,
            KeyAction::DebugShowChunkBorders,
            KeyAction::DebugShowAdvancedTooltips,
            KeyAction::DebugCopyRecreateCommand,
            KeyAction::DebugSpectate,
            KeyAction::DebugSwitchGameMode,
            KeyAction::DebugDebugOptions,
            KeyAction::DebugFocusPause,
            KeyAction::DebugDumpDynamicTextures,
            KeyAction::DebugReloadResourcePacks,
            KeyAction::DebugProfiling,
            KeyAction::DebugCopyLocation,
            KeyAction::DebugDumpVersion,
            KeyAction::DebugProfilingChart,
            KeyAction::DebugFpsCharts,
            KeyAction::DebugNetworkCharts,
            KeyAction::DebugLightmapTexture,
        ] {
            if self.session.controls.matches_input(action, input) {
                self.handle_debug_action(action);
                return true;
            }
        }
        false
    }
    fn handle_debug_action(&mut self, action: KeyAction) {
        match action {
            KeyAction::DebugClearChat => self.gui_manager.clear_chat_messages(false),
            _ => log::debug!("Consumed unsupported debug keybind: {:?}", action),
        }
    }
    fn handle_keybinds(&mut self) {
        while let Some(change) =
            crate::input::keyboard_handler::KeyboardHandler::consume_perspective_change(
                &mut self.session.controls,
                self.camera_type,
            )
        {
            self.camera_type = change.current;
            #[cfg(feature = "shaderpacks")]
            self.invalidate_shader_history();
        }
        while crate::input::keyboard_handler::KeyboardHandler::consume_smooth_camera_toggle(
            &mut self.session.controls,
            &mut self.gui_manager.smooth_camera,
        ) {
            self.gui_manager.save_options();
        }
        while self.session.controls.consume_click(KeyAction::ToggleGui) {
            self.gui_manager.hud_hidden = !self.gui_manager.hud_hidden;
        }
        while self.session.controls.consume_click(KeyAction::DebugOverlay) {
            self.gui_manager.hud.show_debug = !self.gui_manager.hud.show_debug;
        }
        let control_down = self.has_control_down();
        crate::gameplay::session::gameplay_tick::dispatch_menu_keybinds(self, control_down);
    }
    fn update_cursor_grab(&mut self) {
        #[cfg(target_os = "android")]
        if self.content_screen_active() {
            self.reset_android_touch();
        } else {
            self.reset_android_screen_touch();
        }
        let target_mode = if self.content_screen_active() {
            winit::window::CursorGrabMode::None
        } else {
            winit::window::CursorGrabMode::Locked
        };
        #[cfg(not(target_arch = "wasm32"))]
        let cursor_center = self.mouse_handler.update_mouse_grabbed(
            target_mode != winit::window::CursorGrabMode::None,
            self.size.width,
            self.size.height,
        );
        #[cfg(target_arch = "wasm32")]
        self.mouse_handler
            .set_mouse_grabbed(target_mode != winit::window::CursorGrabMode::None);
        #[cfg(target_arch = "wasm32")]
        if target_mode == winit::window::CursorGrabMode::Locked
            && !self.wasm_cursor_grab_input_scope.get()
            && self.current_cursor_grab_mode.get() != Some(winit::window::CursorGrabMode::Locked)
        {
            self.mouse_handler.set_mouse_grabbed(false);
            self.window.set_cursor_visible(true);
            self.current_cursor_grab_mode
                .set(Some(winit::window::CursorGrabMode::None));
            return;
        }
        if self.current_cursor_grab_mode.get() == Some(target_mode) {
            return;
        }
        #[cfg(not(target_arch = "wasm32"))]
        let release_hint_committed = target_mode == winit::window::CursorGrabMode::None
            && cursor_center.is_some_and(|(x, y)| {
                crate::input::cursor_platform::prepare_release(
                    &self.window,
                    winit::dpi::PhysicalPosition::new(x, y),
                )
            });
        if target_mode == winit::window::CursorGrabMode::None {
            self.manual_cursor_grab.set(false);
            let _ = self
                .window
                .set_cursor_grab(winit::window::CursorGrabMode::None);
            self.window.set_cursor_visible(true);
            self.current_cursor_grab_mode
                .set(Some(winit::window::CursorGrabMode::None));
        } else {
            let res = self
                .window
                .set_cursor_grab(winit::window::CursorGrabMode::Locked);
            if res.is_ok() {
                self.manual_cursor_grab.set(false);
                self.window.set_cursor_visible(false);
                self.current_cursor_grab_mode
                    .set(Some(winit::window::CursorGrabMode::Locked));
            } else {
                let res_confined = self
                    .window
                    .set_cursor_grab(winit::window::CursorGrabMode::Confined);
                if res_confined.is_ok() {
                    self.manual_cursor_grab.set(false);
                    self.window.set_cursor_visible(false);
                    self.current_cursor_grab_mode
                        .set(Some(winit::window::CursorGrabMode::Confined));
                } else {
                    self.manual_cursor_grab.set(true);
                    self.window.set_cursor_visible(false);
                    self.center_cursor_in_window();
                    self.current_cursor_grab_mode
                        .set(Some(winit::window::CursorGrabMode::Locked));
                }
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        if let Some((x, y)) = cursor_center {
            let position = winit::dpi::PhysicalPosition::new(x, y);
            let warped =
                release_hint_committed || self.window.set_cursor_position(position).is_ok();
            self.gui_manager.sync_cursor_after_warp(position, warped);
            if target_mode == winit::window::CursorGrabMode::None {
                el_protocol_backend::diagnostics::write_line(&format!(
                    "[CursorDebug] event=release focused={} hint_committed={} warp_accepted={} requested=[{},{}]",
                    self.window.has_focus(),
                    release_hint_committed,
                    warped,
                    x,
                    y,
                ));
            }
        }
    }
    fn center_cursor_in_window(&self) {
        let size = self.window.inner_size();
        if size.width == 0 || size.height == 0 {
            return;
        }
        let _ = self
            .window
            .set_cursor_position(winit::dpi::PhysicalPosition::new(
                f64::from(size.width) * 0.5,
                f64::from(size.height) * 0.5,
            ));
    }
    #[cfg(target_arch = "wasm32")]
    pub fn notify_pointer_lock_lost(&self) {
        if self.current_cursor_grab_mode.get() == Some(winit::window::CursorGrabMode::Locked) {
            log::info!("[WASM] pointer lock lost — will re-request on next click");
            self.current_cursor_grab_mode
                .set(Some(winit::window::CursorGrabMode::None));
        }
    }
