    fn configured_render_distance_chunks(&self) -> u32 {
        self.configured_chunk_distance_option("renderDistance", 2, 32, 12)
    }
    fn prepare_weather_buffers(
        &mut self,
        camera_pos: glam::Vec3,
        partial_tick: f32,
    ) -> Option<(u32, u32)> {
        if self.renderer.weather_textures.is_none() {
            self.renderer.weather_gpu_mesh.index_count = 0;
            return None;
        }
        let Some(sea_level) = self.session.remote_sea_level else {
            self.renderer.weather_gpu_mesh.index_count = 0;
            return None;
        };
        let Some(level) = self.session.level.as_ref() else {
            self.renderer.weather_gpu_mesh.index_count = 0;
            return None;
        };
        let intensity = level.rain_level(partial_tick).clamp(0.0, 1.0);
        if intensity <= 0.0 {
            self.renderer.weather_gpu_mesh.index_count = 0;
            return None;
        }
        let radius = self.configured_chunk_distance_option("weatherRadius", 3, 10, 10) as i32;
        self.renderer.weather_render_state.reset();
        {
            let level = self.session.level.as_ref().expect("level checked above");
            let sampler = ClientLevelWeatherSampler { level, sea_level };
            self.renderer.weather_renderer.extract_render_state(
                &sampler,
                level.game_time(),
                partial_tick,
                camera_pos,
                intensity,
                radius,
                &mut self.renderer.weather_render_state,
            );
        }
        self.renderer.weather_renderer.build_mesh_into(
            camera_pos,
            &self.renderer.weather_render_state,
            &mut self.renderer.weather_cpu_mesh,
        );
        if self.renderer.weather_cpu_mesh.is_empty() {
            self.renderer.weather_gpu_mesh.index_count = 0;
            return None;
        }
        for vertex in &mut self.renderer.weather_cpu_mesh.vertices {
            vertex.position[0] += camera_pos.x;
            vertex.position[1] += camera_pos.y;
            vertex.position[2] += camera_pos.z;
        }
        self.renderer.weather_gpu_mesh.update_from_parts(
            &self.device,
            &self.queue,
            &self.renderer.weather_cpu_mesh.vertices,
            &self.renderer.weather_cpu_mesh.indices,
            "Java Weather",
        );
        Some((
            self.renderer.weather_cpu_mesh.rain_index_count,
            self.renderer.weather_cpu_mesh.snow_index_count,
        ))
    }
    fn configured_cloud_range_chunks(&self) -> u32 {
        self.configured_chunk_distance_option("cloudRange", 2, 128, 128)
    }
    fn effective_render_distance_chunks(&self) -> u32 {
        let configured = self.configured_render_distance_chunks();
        let server_capped =
            if self.session.remote_connection.is_some() && self.remote_chunk_server_radius > 0 {
                configured.min(self.remote_chunk_server_radius as u32)
            } else {
                configured
            };
        #[cfg(target_arch = "wasm32")]
        let server_capped = server_capped.min(8);
        server_capped
    }
    fn entity_view_scale_like_java(&self) -> f32 {
        let entity_distance_scaling = self
            .gui_manager
            .extra_options
            .get("entityDistanceScaling")
            .and_then(|value| value.parse::<f32>().ok())
            .filter(|value| value.is_finite())
            .unwrap_or(1.0)
            .clamp(0.5, 5.0);
        (self.effective_render_distance_chunks() as f32 / 8.0).clamp(1.0, 2.5)
            * entity_distance_scaling
    }
    fn camera_depth_far(&self) -> f32 {
        let render_distance = self.effective_render_distance_chunks() as f32 * 16.0;
        let cloud_range = self.configured_cloud_range_chunks() as f32 * 16.0;
        (render_distance * 4.0).max(cloud_range)
    }
    fn camera_base_fov(&self) -> f32 {
        el_gui::settings::options::fov_degrees_from_slider(self.gui_manager.fov_setting) as f32
    }
    fn camera_fov_effect_scale(&self) -> f32 {
        self.gui_manager
            .extra_options
            .get("fovEffectScale")
            .and_then(|value| value.parse::<f32>().ok())
            .filter(|value| value.is_finite())
            .unwrap_or(1.0)
            .clamp(0.0, 1.0)
            .powi(2)
    }
    fn camera_target_fov_modifier(&self) -> f32 {
        if !self.is_controlled_camera() {
            return 1.0;
        }
        let mut modifier = 1.0;
        let abilities = self.session.game_mode.abilities();
        if abilities.flying {
            modifier *= 1.1;
        }
        if abilities.walking_speed != 0.0 {
            let speed_factor =
                self.session
                    .player
                    .attr_f64(crate::gameplay::attributes::MOVEMENT_SPEED) as f32
                    / abilities.walking_speed;
            modifier *= (speed_factor + 1.0) / 2.0;
        }
        if self.session.player.is_using_item {
            if let Some(location) = self.session.active_using_item_location() {
                if location.namespace == "minecraft" && location.path == "bow" {
                    let scale =
                        ((self.session.item_use.duration - self.session.item_use.remaining) / 20.0)
                            .min(1.0);
                    modifier *= 1.0 - scale * scale * 0.15;
                } else if self.camera_type.is_first_person() && self.player_is_scoping() {
                    return 0.1;
                }
            }
        }
        1.0 + self.camera_fov_effect_scale() * (modifier - 1.0)
    }
    fn camera_death_time(&self) -> Option<f32> {
        if self.is_controlled_camera() {
            return self
                .session
                .player
                .is_dead_or_dying()
                .then_some(self.session.player.death_time as f32);
        }
        let entity = self.session.remote_entities.get(&self.camera_entity_id?)?;
        (entity.uses_living_body_rotation() && entity.living_health <= 0.0)
            .then_some(entity.death_time)
    }
    fn camera_hurt_state(&self) -> Option<(f32, f32, f32)> {
        if self.is_controlled_camera() {
            return Some((
                self.session.player.hurt_time as f32,
                self.session.player.hurt_duration as f32,
                self.session.player.hurt_dir,
            ));
        }
        let entity = self.session.remote_entities.get(&self.camera_entity_id?)?;
        entity.uses_living_body_rotation().then_some((
            entity.hurt_time,
            entity.hurt_duration,
            entity.hurt_dir,
        ))
    }
    fn update_camera_projection(&mut self, partial_tick: f32) {
        let base_fov = self.camera_base_fov();
        let damage_tilt_strength = self.gui_manager.damage_tilt_strength;
        #[cfg(feature = "extensions")]
        let hook_camera = crate::modding::hooks::camera_transform(
            crate::modding::client_content::camera_hurt_scale_milli(),
        );
        #[cfg(feature = "extensions")]
        let damage_tilt_strength = crate::modding::camera::scaled_strength(
            damage_tilt_strength,
            hook_camera.hurt_scale_milli,
        );
        #[cfg(feature = "shaderpacks")]
        {
            let settings = [
                u64::from(base_fov.to_bits()),
                u64::from(self.camera_fov_effect_scale().to_bits()),
                damage_tilt_strength.to_bits(),
            ];
            if self
                .shader_camera_settings
                .replace(settings)
                .is_some_and(|old| old != settings)
            {
                self.invalidate_shader_history();
            }
        }
        let fluid = self
            .session
            .level
            .as_ref()
            .map(|level| self.camera.fluid_in_camera(level, base_fov))
            .unwrap_or(crate::gameplay::camera::FogType::None);
        self.camera.update_projection(
            partial_tick,
            base_fov,
            self.camera_fov_effect_scale(),
            self.camera_death_time(),
            self.camera_hurt_state(),
            damage_tilt_strength,
            fluid,
            self.config.width.max(1) as f32,
            self.config.height.max(1) as f32,
            self.camera_depth_far(),
        );
        #[cfg(feature = "extensions")]
        {
            let hurt = crate::modding::hooks::camera_hurt(self.camera.hurt_render_angles());
            self.camera
                .set_hurt_render_angles(hurt.enabled, hurt.angles_degrees);
        }
        #[cfg(feature = "extensions")]
        self.camera
            .set_mod_render_transform(hook_camera.rotation_radians, hook_camera.fov_scale_milli);
    }
    fn player_head_item_texture_key(&mut self, stack: Option<&ItemStack>) -> Option<String> {
        let stack = stack?;
        if stack.item.location.path != "player_head" {
            return None;
        }
        if let Some(url) = player_head_skin_url_from_item(stack) {
            let key = player_head_texture_key(&url);
            if !self.renderer.remote_entity_textures.contains_key(&key) {
                self.queue_remote_dynamic_texture_download(key, &url);
                return None;
            }
            return Some(key);
        }
        let profile_uuid =
            player_head_profile_uuid_from_item(stack).unwrap_or_else(uuid::Uuid::nil);
        if let Some(url) = self
            .remote_player_skins
            .get(&profile_uuid)
            .and_then(|skin| skin.texture_url.as_deref())
            .map(str::to_owned)
        {
            let key = format!("player_skin:{profile_uuid}");
            if !self.renderer.remote_entity_textures.contains_key(&key) {
                self.queue_remote_dynamic_texture_download(key, &url);
                return None;
            }
            return Some(key);
        }
        let default_path = default_player_skin_texture_path(profile_uuid);
        self.ensure_remote_entity_texture_path_loaded(default_path);
        self.renderer
            .remote_entity_textures
            .contains_key(default_path)
            .then(|| default_path.to_string())
    }
    fn calculate_item_pull_stage(
        stack: Option<&ItemStack>,
        using_item: bool,
        use_ticks: f32,
    ) -> u8 {
        if !using_item {
            return 0;
        }
        let Some(stack) = stack else {
            return 0;
        };
        if stack.is_vanilla_bow_item() {
            if use_ticks < 13.0 {
                1
            } else if use_ticks < 18.0 {
                2
            } else {
                3
            }
        } else if stack.item.location.path == "crossbow" {
            if use_ticks < 14.5 {
                1
            } else if use_ticks < 25.0 {
                2
            } else {
                3
            }
        } else {
            0
        }
    }
    fn tick_item_in_hand_once(&mut self) {
        self.o_main_hand_height = self.main_hand_height;
        self.o_off_hand_height = self.off_hand_height;
        let next_main_hand = self.session.active_held_item_location();
        let next_main_stack = {
            let s = &self.session.player.inventory[self.session.active_hotbar_slot];
            if s.is_empty() { None } else { Some(s.clone()) }
        };
        let next_main_custom_texture_key =
            self.player_head_item_texture_key(next_main_stack.as_ref());
        let next_main_using_item_context =
            self.session.item_use.hand == Some(self.local_main_hand_side());
        let next_main_use_ticks = if next_main_using_item_context {
            (self.session.item_use.duration - self.session.item_use.remaining).max(0.0)
        } else {
            0.0
        };
        let next_main_pull_stage = Self::calculate_item_pull_stage(
            next_main_stack.as_ref(),
            next_main_using_item_context,
            next_main_use_ticks,
        );
        let swap_charge = self.session.player.item_swap_scale(1.0);
        let main_target_height = swap_charge * swap_charge * swap_charge;
        let hands_busy = self.session.local_player_hands_busy_like_java();
        let main_properties = crate::render::prepare_hand::HandItemProperties::for_stack(
            next_main_stack.as_ref(),
            &self.gui_manager.renderer.item_definitions,
        );
        let main_plan = crate::render::prepare_hand::plan_hand_tick(
            self.main_hand_height,
            &self.renderer.held_item_texture,
            &self.renderer.held_item_stack,
            &self.renderer.held_item_custom_texture_key,
            self.renderer.held_item_using_item_context,
            self.renderer.held_item_pull_stage,
            &next_main_hand,
            &next_main_stack,
            &next_main_custom_texture_key,
            next_main_using_item_context,
            next_main_pull_stage,
            main_target_height,
            hands_busy,
            main_properties.hand_animation_on_swap,
        );
        if main_plan.instant_replace {
            self.set_held_item_texture(
                next_main_hand.clone(),
                next_main_stack.as_ref(),
                next_main_using_item_context,
                next_main_use_ticks,
                next_main_pull_stage,
            );
        }
        self.main_hand_height = main_plan.new_height;
        if main_plan.swap {
            self.set_held_item_texture(
                next_main_hand,
                next_main_stack.as_ref(),
                next_main_using_item_context,
                next_main_use_ticks,
                next_main_pull_stage,
            );
        }
        let next_offhand = self.session.active_offhand_item_location();
        let next_off_stack = if self.session.player.inventory.len() > 40 {
            let s = &self.session.player.inventory[40];
            if s.is_empty() { None } else { Some(s.clone()) }
        } else {
            None
        };
        let next_off_custom_texture_key =
            self.player_head_item_texture_key(next_off_stack.as_ref());
        let next_off_using_item_context = self.session.item_use.hand
            == Some(Self::opposite_hand_side(self.local_main_hand_side()));
        let next_off_use_ticks = if next_off_using_item_context {
            (self.session.item_use.duration - self.session.item_use.remaining).max(0.0)
        } else {
            0.0
        };
        let next_off_pull_stage = Self::calculate_item_pull_stage(
            next_off_stack.as_ref(),
            next_off_using_item_context,
            next_off_use_ticks,
        );
        let off_properties = crate::render::prepare_hand::HandItemProperties::for_stack(
            next_off_stack.as_ref(),
            &self.gui_manager.renderer.item_definitions,
        );
        let off_plan = crate::render::prepare_hand::plan_hand_tick(
            self.off_hand_height,
            &self.renderer.off_hand_item_texture,
            &self.renderer.off_hand_item_stack,
            &self.renderer.off_hand_item_custom_texture_key,
            self.renderer.off_hand_item_using_item_context,
            self.renderer.off_hand_item_pull_stage,
            &next_offhand,
            &next_off_stack,
            &next_off_custom_texture_key,
            next_off_using_item_context,
            next_off_pull_stage,
            1.0,
            hands_busy,
            off_properties.hand_animation_on_swap,
        );
        if off_plan.instant_replace {
            self.set_offhand_item_texture(
                next_offhand.clone(),
                next_off_stack.as_ref(),
                next_off_using_item_context,
                next_off_use_ticks,
                next_off_pull_stage,
            );
        }
        self.off_hand_height = off_plan.new_height;
        if off_plan.swap {
            self.set_offhand_item_texture(
                next_offhand,
                next_off_stack.as_ref(),
                next_off_using_item_context,
                next_off_use_ticks,
                next_off_pull_stage,
            );
        }
    }
    fn interpolated_main_hand_height(&self) -> f32 {
        self.o_main_hand_height
            + (self.main_hand_height - self.o_main_hand_height) * self.session.render_partial_tick()
    }
    fn interpolated_off_hand_height(&self) -> f32 {
        self.o_off_hand_height
            + (self.off_hand_height - self.o_off_hand_height) * self.session.render_partial_tick()
    }
    fn set_held_item_texture(
        &mut self,
        target_held_loc: Option<String>,
        stack: Option<&ItemStack>,
        using_item_context: bool,
        use_ticks: f32,
        pull_stage: u8,
    ) {
        self.renderer.held_item_texture = target_held_loc.clone();
        self.renderer.held_item_stack = stack.cloned();
        self.renderer.held_item_custom_texture_key = self.player_head_item_texture_key(stack);
        self.renderer.held_item_using_item_context = using_item_context;
        self.renderer.held_item_pull_stage = pull_stage;
        if let Some(loc_str) = target_held_loc {
            let Some(ref atlas) = self.renderer.block_atlas else {
                self.renderer.held_item_vertex_buffer = None;
                self.renderer.held_item_index_buffer = None;
                self.renderer.held_item_num_indices = 0;
                self.renderer.third_person_main_item_vertex_buffer = None;
                self.renderer.third_person_main_item_index_buffer = None;
                self.renderer.third_person_main_item_num_indices = 0;
                return;
            };
            let item_loc = el_core::resource_location::ResourceLocation::from_string(&loc_str);
            let block_colors = self.session.level.as_ref().map(|level| &level.block_colors);
            let main_hand_side = self.local_main_hand_side();
            let (vertices, indices) = if self.renderer.held_item_custom_texture_key.is_some() {
                generate_player_head_item_mesh(
                    &item_loc,
                    &self.resource_manager,
                    main_hand_side,
                    HeldItemDisplay::FirstPerson,
                )
            } else {
                generate_held_item_mesh_for_display_with_use(
                    &item_loc,
                    atlas,
                    &self.resource_manager,
                    main_hand_side,
                    HeldItemDisplay::FirstPerson,
                    block_colors,
                    stack,
                    using_item_context,
                    use_ticks,
                )
            };
            let (tp_vertices, tp_indices) = if self.renderer.held_item_custom_texture_key.is_some()
            {
                generate_player_head_item_mesh(
                    &item_loc,
                    &self.resource_manager,
                    main_hand_side,
                    HeldItemDisplay::ThirdPerson,
                )
            } else {
                generate_held_item_mesh_for_display_with_use(
                    &item_loc,
                    atlas,
                    &self.resource_manager,
                    main_hand_side,
                    HeldItemDisplay::ThirdPerson,
                    block_colors,
                    stack,
                    using_item_context,
                    use_ticks,
                )
            };
            self.install_held_item_mesh(vertices, indices);
            self.install_third_person_main_item_mesh(tp_vertices, tp_indices);
        } else {
            self.renderer.held_item_vertex_buffer = None;
            self.renderer.held_item_index_buffer = None;
            self.renderer.held_item_num_indices = 0;
            self.renderer.third_person_main_item_vertex_buffer = None;
            self.renderer.third_person_main_item_index_buffer = None;
            self.renderer.third_person_main_item_num_indices = 0;
            self.renderer.held_item_custom_texture_key = None;
            self.renderer.held_item_using_item_context = false;
            self.renderer.held_item_pull_stage = 0;
        }
    }
