fn client_biome_from_network(data: BiomeRenderData) -> crate::render::block_colors::Biome {
    let modifier = match data.grass_color_modifier.as_str() {
        "dark_forest" => crate::render::block_colors::GrassColorModifier::DarkForest,
        "swamp" => crate::render::block_colors::GrassColorModifier::Swamp,
        _ => crate::render::block_colors::GrassColorModifier::None,
    };
    crate::render::block_colors::Biome {
        id: data.id,
        has_precipitation: data.has_precipitation,
        temperature: data.temperature,
        temperature_modifier: data.temperature_modifier,
        downfall: data.downfall,
        water_color: data.water_color,
        foliage_color_override: data.foliage_color,
        dry_foliage_color_override: data.dry_foliage_color,
        grass_color_override: data.grass_color,
        grass_color_modifier: modifier,
    }
}
struct SpecialVertex {
    pos: glam::Vec3,
    uv: [f32; 2],
}
struct SpecialPolygon {
    vertices: [SpecialVertex; 4],
    normal: glam::Vec3,
}
fn part_matrix(pose: &el_inventory::special::SpecialPartPose) -> glam::Mat4 {
    glam::Mat4::from_translation(
        glam::Vec3::new(pose.offset[0], pose.offset[1], pose.offset[2]) / 16.0,
    ) * glam::Mat4::from_euler(
        glam::EulerRot::ZYX,
        pose.rotation[2],
        pose.rotation[1],
        pose.rotation[0],
    ) * glam::Mat4::from_scale(glam::Vec3::new(pose.scale[0], pose.scale[1], pose.scale[2]))
}
fn cube_polygons(cube: &el_inventory::special::SpecialModelCube) -> Vec<SpecialPolygon> {
    let mut min_x = cube.origin[0] - cube.grow[0];
    let min_y = cube.origin[1] - cube.grow[1];
    let min_z = cube.origin[2] - cube.grow[2];
    let mut max_x = cube.origin[0] + cube.dimensions[0] + cube.grow[0];
    let max_y = cube.origin[1] + cube.dimensions[1] + cube.grow[1];
    let max_z = cube.origin[2] + cube.dimensions[2] + cube.grow[2];
    if cube.mirror {
        std::mem::swap(&mut min_x, &mut max_x);
    }
    let t0 = glam::Vec3::new(min_x, min_y, min_z);
    let t1 = glam::Vec3::new(max_x, min_y, min_z);
    let t2 = glam::Vec3::new(max_x, max_y, min_z);
    let t3 = glam::Vec3::new(min_x, max_y, min_z);
    let l0 = glam::Vec3::new(min_x, min_y, max_z);
    let l1 = glam::Vec3::new(max_x, min_y, max_z);
    let l2 = glam::Vec3::new(max_x, max_y, max_z);
    let l3 = glam::Vec3::new(min_x, max_y, max_z);
    let width = cube.dimensions[0];
    let height = cube.dimensions[1];
    let depth = cube.dimensions[2];
    let u0 = cube.tex_offs[0];
    let u1 = cube.tex_offs[0] + depth;
    let u2 = cube.tex_offs[0] + depth + width;
    let u22 = cube.tex_offs[0] + depth + width + width;
    let u3 = cube.tex_offs[0] + depth + width + depth;
    let u4 = cube.tex_offs[0] + depth + width + depth + width;
    let v0 = cube.tex_offs[1];
    let v1 = cube.tex_offs[1] + depth;
    let v2 = cube.tex_offs[1] + depth + height;
    let mut polygons = Vec::with_capacity(6);
    let mut push_poly = |facing: Direction, mut vertices: [glam::Vec3; 4], uv_rect: [f32; 4]| {
        let face_idx = match facing {
            Direction::Down => 0,
            Direction::Up => 1,
            Direction::North => 2,
            Direction::South => 3,
            Direction::West => 4,
            Direction::East => 5,
        };
        if !cube.visible_faces[face_idx] {
            return;
        }
        let [tu0, tv0, tu1, tv1] = uv_rect;
        let tex_width = cube.tex_size[0];
        let tex_height = cube.tex_size[1];
        let uv0 = [tu1 / tex_width, tv0 / tex_height];
        let uv1 = [tu0 / tex_width, tv0 / tex_height];
        let uv2 = [tu0 / tex_width, tv1 / tex_height];
        let uv3 = [tu1 / tex_width, tv1 / tex_height];
        let normal_facing = if cube.mirror {
            vertices.reverse();
            match facing {
                Direction::East => Direction::West,
                Direction::West => Direction::East,
                _ => facing,
            }
        } else {
            facing
        };
        polygons.push(SpecialPolygon {
            vertices: [
                SpecialVertex {
                    pos: vertices[0],
                    uv: uv0,
                },
                SpecialVertex {
                    pos: vertices[1],
                    uv: uv1,
                },
                SpecialVertex {
                    pos: vertices[2],
                    uv: uv2,
                },
                SpecialVertex {
                    pos: vertices[3],
                    uv: uv3,
                },
            ],
            normal: direction_normal(normal_facing),
        });
    };
    push_poly(Direction::Down, [l1, l0, t0, t1], [u1, v0, u2, v1]);
    push_poly(Direction::Up, [t2, t3, l3, l2], [u2, v1, u22, v0]);
    push_poly(Direction::West, [t0, l0, l3, t3], [u0, v1, u1, v2]);
    push_poly(Direction::North, [t1, t0, t3, t2], [u1, v1, u2, v2]);
    push_poly(Direction::East, [l1, t1, t2, l2], [u2, v1, u3, v2]);
    push_poly(Direction::South, [l0, l1, l2, l3], [u3, v1, u4, v2]);
    polygons
}
fn collect_special_part_vertices(
    part: &el_inventory::special::SpecialModelPart,
    parent_matrix: glam::Mat4,
    color: [f32; 4],
    sprite_rect: SpriteUvRect,
    vertices: &mut Vec<Vertex>,
    indices: &mut Vec<u32>,
) {
    let part_matrix = parent_matrix * part_matrix(&part.pose);
    let part_color = multiply_color(color, part.color);
    for cube in &part.cubes {
        for polygon in cube_polygons(cube) {
            let start = vertices.len() as u32;
            let normal = part_matrix
                .transform_vector3(polygon.normal)
                .normalize_or_zero();
            for vertex in &polygon.vertices {
                let local_pos = vertex.pos / 16.0;
                let transformed_pos = part_matrix.transform_point3(local_pos);
                let u = sprite_rect.u0 + (sprite_rect.u1 - sprite_rect.u0) * vertex.uv[0];
                let v = sprite_rect.v0 + (sprite_rect.v1 - sprite_rect.v0) * vertex.uv[1];
                vertices.push(Vertex {
                    position: [transformed_pos.x, transformed_pos.y, transformed_pos.z],
                    tex_coords: [u, v],
                    normal: [normal.x, normal.y, normal.z],
                    color: part_color,
                    light: [1.0, 1.0],
                });
            }
            if part_matrix.determinant() < 0.0 {
                indices.extend_from_slice(&[
                    start,
                    start + 2,
                    start + 1,
                    start,
                    start + 3,
                    start + 2,
                ]);
            } else {
                indices.extend_from_slice(&[
                    start,
                    start + 1,
                    start + 2,
                    start,
                    start + 2,
                    start + 3,
                ]);
            }
        }
    }
    for child in &part.children {
        collect_special_part_vertices(
            child,
            part_matrix,
            part_color,
            sprite_rect,
            vertices,
            indices,
        );
    }
}
impl crate::gameplay::session::gameplay_tick::GameplayTickHost for State {
    fn open_chat_screen(&mut self, initial: Option<String>) {
        self.open_chat_screen(initial.as_deref());
    }
    fn open_inventory_screen(&mut self) {
        self.open_inventory_screen();
    }
    fn open_advancements_screen(&mut self) {
        self.gui_manager.toggle_advancements_screen();
        self.session.controls.release_all();
        self.session.sync_player_input_from_key_mappings(
            crate::gameplay::session::phases::InputOptions {
                toggle_crouch: self.gui_manager.toggle_crouch,
                toggle_sprint: self.gui_manager.toggle_sprint,
                toggle_attack: self.gui_manager.toggle_attack,
                toggle_use: self.gui_manager.toggle_use,
            },
        );
        self.update_cursor_grab();
    }
    fn attempt_block_use(&mut self, hand: usize) -> bool {
        use crate::gameplay::session::gameplay_tick::predict_block_use;
        let main_hand = self.local_main_hand_side();
        let screen_active = self.gui_manager.is_screen_active();
        let prediction = predict_block_use(&mut self.session, main_hand, screen_active, hand);
        let stops_hand_iteration = prediction.stops_hand_iteration();
        for sound in prediction.interaction_sounds {
            use el_math::random::RandomSource;
            let pitch = self.sound_variant_random.next_float() * sound.pitch_random_range
                + sound.pitch_base;
            self.play_local_sound(
                sound.sound_event,
                crate::client::sound_engine::SoundSource::Blocks,
                glam::Vec3::new(
                    sound.pos.x as f32 + 0.5,
                    sound.pos.y as f32 + 0.5,
                    sound.pos.z as f32 + 0.5,
                ),
                sound.volume,
                pitch,
            );
        }
        if let Some((placed_pos, placed_state)) = prediction.place_sound {
            if crate::client::state::has_special_block_entity_renderer(&placed_state.block.path) {
                self.renderer.block_entity_mesh_dirty = true;
            }
            self.play_block_sound_type(
                &placed_state,
                crate::client::state::BlockSoundKind::Place,
                glam::Vec3::new(
                    placed_pos.x as f32 + 0.5,
                    placed_pos.y as f32 + 0.5,
                    placed_pos.z as f32 + 0.5,
                ),
                crate::client::sound_engine::SoundSource::Blocks,
            );
        }
        if self.session.remote_connection.is_some() && !prediction.chest_updates.is_empty() {
            let chest_neighbor_positions =
                self.mirror_remote_chest_neighbor_shape_updates(prediction.chest_updates);
            for neighbor_pos in chest_neighbor_positions {
                self.queue_remote_sections_around_block(neighbor_pos, true);
                self.queue_remote_light_section_mesh(
                    crate::client::state::RenderSectionKey::from_block_pos(neighbor_pos),
                );
            }
            self.process_urgent_remote_chunk_mesh_queue();
        }
        for (pos, target_state) in prediction.local_updates {
            self.update_block_locally(pos, target_state);
        }
        stops_hand_iteration
    }
}
impl crate::gameplay::session::screen_tick::ScreenTickHost for State {
    fn begin_tick_observation(&mut self) {
        self.renderer.render_profiler.begin_client_tick();
    }
    fn finish_tick_observation(&mut self) {
        self.renderer.render_profiler.finish_client_tick();
    }
    fn session(&self) -> &crate::gameplay::session::ClientSession {
        &self.session
    }
    fn session_mut(&mut self) -> &mut crate::gameplay::session::ClientSession {
        &mut self.session
    }
    fn tick_connection_loading(&mut self) {
        self.maybe_send_player_loaded();
    }
    fn tick_gui(&mut self) {
        let gui_tick_started_at = Instant::now();
        let sprint_window_ticks = self
            .gui_manager
            .extra_options
            .get("sprintWindow")
            .and_then(|encoded| el_gui::settings::controls::decode_sprint_window_option(encoded))
            .map(|ticks| ticks.round() as i32)
            .unwrap_or(7);
        self.session
            .player
            .set_sprint_window_ticks_like_java(sprint_window_ticks);
        self.gui_manager.tick(
            self.session.level.as_mut(),
            &mut self.session.player,
            self.session.active_hotbar_slot,
            1,
            self.session.remote_show_death_screen,
            self.session.remote_level_hardcore,
        );
        if self.gui_manager.take_win_screen_respawn_request() {
            self.session
                .send_perform_respawn_if_needed("win_screen_finished", true);
            self.update_cursor_grab();
        }
        self.consume_death_screen_respawn_request("death_screen_tick_fallback");
        self.renderer
            .render_profiler
            .observe("State::update::gui_tick", gui_tick_started_at.elapsed());
        self.sync_biome_blend_radius_like_java();
        if self.session.remote_connection.is_some()
            && self.session.player_loaded_sent
            && self.gui_manager.is_level_loading_screen_active()
        {
            self.gui_manager.finish_level_loading_screen();
            self.update_cursor_grab();
        }
    }
    fn screen_active(&self) -> bool {
        self.content_screen_active()
    }
    fn handle_keybinds(&mut self) {
        State::handle_keybinds(self);
    }
    fn input_options(&self) -> crate::gameplay::session::phases::InputOptions {
        crate::gameplay::session::phases::InputOptions {
            toggle_crouch: self.gui_manager.toggle_crouch,
            toggle_sprint: self.gui_manager.toggle_sprint,
            toggle_attack: self.gui_manager.toggle_attack,
            toggle_use: self.gui_manager.toggle_use,
        }
    }
    fn tick_camera(&mut self) {
        self.tick_camera_after_keybinds();
    }
    fn tick_active_item_use(&mut self) {
        self.tick_active_use_item_after_camera();
    }
    fn before_remote_entity_tick(&mut self) {
        self.session.remote_push_policy =
            crate::gameplay::session::phases::RemoteEntityPushPolicy::from_scoreboard(
                self.gui_manager.player_username(),
                self.session.remote_player_entity_id,
                &self.session.remote_entities,
                self.gui_manager.scoreboard(),
                self.gui_manager.player_infos(),
            );
        self.debug_subscriber
            .purge_expired(self.session.client_level_game_time());
    }
    fn apply_remote_entity_effects(
        &mut self,
        output: crate::gameplay::entity::remote::RemoteEntitiesTickOutput,
    ) {
        for (particle, pos, velocity) in output.projectile_particles {
            self.particle_engine
                .spawn_network_particle(&particle, pos, velocity, None);
        }
    }
    fn tick_controlled_vehicle(&mut self, id: i32) -> Option<(bool, bool)> {
        State::tick_controlled_vehicle(self, id)
    }
    fn attach_player_to_vehicle(&mut self, id: i32) {
        self.attach_local_player_to_remote_vehicle(id);
    }
    fn latch_vehicle_input(&mut self, id: i32) {
        self.latch_remote_boat_input_after_ride_tick(id);
    }
    fn main_hand(&self) -> crate::render::model::player::player_model::HandSide {
        self.local_main_hand_side()
    }
    fn controlled_camera(&self) -> bool {
        self.is_controlled_camera()
    }
    fn auto_jump_enabled(&self) -> bool {
        self.auto_jump_option_enabled()
    }
    fn tick_level_effects(&mut self, runs_normally: bool) {
        self.tick_level_presentation_after_entities(runs_normally);
    }
}
struct SpecialInfo {
    model: el_inventory::special::UnbakedSpecialModel,
    base: Option<el_core::resource_location::ResourceLocation>,
    extra_transform: glam::Mat4,
}
fn parse_json_transformation(val: &serde_json::Value) -> glam::Mat4 {
    let mut translation = glam::Vec3::ZERO;
    let mut left_rot = glam::Quat::IDENTITY;
    let mut scale = glam::Vec3::ONE;
    let mut right_rot = glam::Quat::IDENTITY;
    if let Some(obj) = val.as_object() {
        if let Some(t_val) = obj.get("translation").and_then(|v| v.as_array()) {
            if t_val.len() >= 3 {
                let tx = t_val[0].as_f64().unwrap_or(0.0) as f32;
                let ty = t_val[1].as_f64().unwrap_or(0.0) as f32;
                let tz = t_val[2].as_f64().unwrap_or(0.0) as f32;
                translation = glam::Vec3::new(tx, ty, tz);
            }
        }
        if let Some(s_val) = obj.get("scale").and_then(|v| v.as_array()) {
            if s_val.len() >= 3 {
                let sx = s_val[0].as_f64().unwrap_or(1.0) as f32;
                let sy = s_val[1].as_f64().unwrap_or(1.0) as f32;
                let sz = s_val[2].as_f64().unwrap_or(1.0) as f32;
                scale = glam::Vec3::new(sx, sy, sz);
            }
        }
        let parse_rot = |v_arr: &[serde_json::Value]| -> Option<glam::Quat> {
            if v_arr.len() == 4 {
                let x = v_arr[0].as_f64().unwrap_or(0.0) as f32;
                let y = v_arr[1].as_f64().unwrap_or(0.0) as f32;
                let z = v_arr[2].as_f64().unwrap_or(0.0) as f32;
                let w = v_arr[3].as_f64().unwrap_or(1.0) as f32;
                Some(glam::Quat::from_xyzw(x, y, z, w))
            } else if v_arr.len() == 3 {
                let rx = (v_arr[0].as_f64().unwrap_or(0.0) as f32).to_radians();
                let ry = (v_arr[1].as_f64().unwrap_or(0.0) as f32).to_radians();
                let rz = (v_arr[2].as_f64().unwrap_or(0.0) as f32).to_radians();
                Some(glam::Quat::from_euler(glam::EulerRot::XYZ, rx, ry, rz))
            } else {
                None
            }
        };
        if let Some(r_val) = obj.get("left_rotation").and_then(|v| v.as_array()) {
            if let Some(q) = parse_rot(r_val) {
                left_rot = q;
            }
        }
        if let Some(r_val) = obj.get("right_rotation").and_then(|v| v.as_array()) {
            if let Some(q) = parse_rot(r_val) {
                right_rot = q;
            }
        }
        if let Some(r_val) = obj.get("rotation").and_then(|v| v.as_array()) {
            if let Some(q) = parse_rot(r_val) {
                left_rot = q;
            }
        }
    }
    glam::Mat4::from_translation(translation)
        * glam::Mat4::from_quat(left_rot)
        * glam::Mat4::from_scale(scale)
        * glam::Mat4::from_quat(right_rot)
}
fn find_special_model(
    value: &serde_json::Value,
    current_transform: glam::Mat4,
) -> Option<SpecialInfo> {
    find_special_model_with_using_item(value, current_transform, false)
}
fn find_special_model_with_using_item(
    value: &serde_json::Value,
    current_transform: glam::Mat4,
    using_item: bool,
) -> Option<SpecialInfo> {
    let obj = value.as_object()?;
    let parsed_transform = if let Some(t_node) = obj.get("transformation") {
        parse_json_transformation(t_node)
    } else {
        glam::Mat4::IDENTITY
    };
    let node_transform = current_transform * parsed_transform;
    let ty = obj.get("type").and_then(|v| v.as_str()).unwrap_or("");
    if ty == "minecraft:special" || ty == "special" {
        let base_loc = obj
            .get("base")
            .and_then(|v| v.as_str())
            .map(el_core::resource_location::ResourceLocation::from_string);
        if let Some(model_val) = obj.get("model") {
            if let Ok(unbaked) = serde_json::from_value::<el_inventory::special::UnbakedSpecialModel>(
                model_val.clone(),
            ) {
                return Some(SpecialInfo {
                    model: unbaked,
                    base: base_loc,
                    extra_transform: node_transform,
                });
            }
        }
    }
    if obj
        .get("property")
        .and_then(|value| value.as_str())
        .is_some_and(|property| property == "minecraft:using_item" || property == "using_item")
    {
        let branch = if using_item { "on_true" } else { "on_false" };
        if let Some(value) = obj.get(branch) {
            return find_special_model_with_using_item(value, node_transform, using_item);
        }
    }
    for key in ["fallback", "model"] {
        if let Some(val) = obj.get(key) {
            if let Some(info) = find_special_model_with_using_item(val, node_transform, using_item)
            {
                return Some(info);
            }
        }
    }
    if let Some(entries) = obj.get("entries").and_then(|v| v.as_array()) {
        for entry in entries {
            let child = entry.get("model").unwrap_or(entry);
            if let Some(info) =
                find_special_model_with_using_item(child, node_transform, using_item)
            {
                return Some(info);
            }
        }
    }
    if let Some(cases) = obj.get("cases").and_then(|v| v.as_array()) {
        for case in cases {
            let child = case.get("model").unwrap_or(case);
            if let Some(info) =
                find_special_model_with_using_item(child, node_transform, using_item)
            {
                return Some(info);
            }
        }
    }
    if let Some(models) = obj.get("models").and_then(|v| v.as_array()) {
        for m_val in models {
            let child = m_val.get("model").unwrap_or(m_val);
            if let Some(info) =
                find_special_model_with_using_item(child, node_transform, using_item)
            {
                return Some(info);
            }
        }
    }
    None
}
fn multiply_color(left: [f32; 4], right: [f32; 4]) -> [f32; 4] {
    [
        left[0] * right[0],
        left[1] * right[1],
        left[2] * right[2],
        left[3] * right[3],
    ]
}
