fn load_world_glint_bind_group(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    texture_bind_group_layout: &wgpu::BindGroupLayout,
    resource_manager: &crate::resources::manager::ClientResourceManager,
    texture_id: &ResourceLocation,
    label: &str,
) -> wgpu::BindGroup {
    let (rgba, width, height) = match resource_manager.read_image(texture_id) {
        Ok(image) => {
            let rgba = image.to_rgba8();
            let (width, height) = rgba.dimensions();
            (rgba.into_raw(), width, height)
        }
        Err(error) => {
            log::warn!(
                "[Render] foil texture unavailable id={} label={label}; using white fallback: {error}",
                texture_id
            );
            (vec![255, 255, 255, 255], 1, 1)
        }
    };
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some(label),
        size: wgpu::Extent3d {
            width,
            height,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Rgba8Unorm,
        usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
        view_formats: &[],
    });
    queue.write_texture(
        wgpu::ImageCopyTexture {
            texture: &texture,
            mip_level: 0,
            origin: wgpu::Origin3d::ZERO,
            aspect: wgpu::TextureAspect::All,
        },
        &rgba,
        wgpu::ImageDataLayout {
            offset: 0,
            bytes_per_row: Some(4 * width),
            rows_per_image: Some(height),
        },
        wgpu::Extent3d {
            width,
            height,
            depth_or_array_layers: 1,
        },
    );
    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    let sampler = device.create_sampler(&wgpu::SamplerDescriptor {
        address_mode_u: wgpu::AddressMode::Repeat,
        address_mode_v: wgpu::AddressMode::Repeat,
        address_mode_w: wgpu::AddressMode::Repeat,
        mag_filter: wgpu::FilterMode::Linear,
        min_filter: wgpu::FilterMode::Linear,
        mipmap_filter: wgpu::FilterMode::Linear,
        ..Default::default()
    });
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        layout: texture_bind_group_layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: wgpu::BindingResource::TextureView(&view),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: wgpu::BindingResource::Sampler(&sampler),
            },
        ],
        label: Some(label),
    })
}
fn player_head_skin_url_from_item(item: &ItemStack) -> Option<String> {
    let DataComponent::Generic {
        value: Tag::Compound(profile),
        ..
    } = item.components.get("minecraft:profile")?
    else {
        return None;
    };
    let properties = compound_get(profile, "properties")?;
    let mut texture_values = Vec::new();
    match properties {
        Tag::List(properties) => {
            for property in properties {
                let Tag::Compound(property) = property else {
                    continue;
                };
                if matches!(
                    compound_get(property, "name"), Some(Tag::String(name)) if name ==
                    "textures"
                ) && let Some(Tag::String(encoded)) = compound_get(property, "value")
                {
                    texture_values.push(encoded.as_str());
                }
            }
        }
        Tag::Compound(properties) => {
            if let Some((_, value)) = properties.iter().find(|(name, _)| name == "textures") {
                match value {
                    Tag::List(values) => {
                        for value in values {
                            if let Tag::Compound(property) = value
                                && let Some(Tag::String(encoded)) = compound_get(property, "value")
                            {
                                texture_values.push(encoded.as_str());
                            }
                        }
                    }
                    Tag::Compound(property) => {
                        if let Some(Tag::String(encoded)) = compound_get(property, "value") {
                            texture_values.push(encoded.as_str());
                        }
                    }
                    _ => {}
                }
            }
        }
        _ => {}
    }
    for encoded in texture_values {
        let bytes =
            base64::Engine::decode(&base64::engine::general_purpose::STANDARD, encoded).ok()?;
        let payload = serde_json::from_slice::<serde_json::Value>(&bytes).ok()?;
        return payload
            .get("textures")
            .and_then(|textures| textures.get("SKIN"))
            .and_then(|skin| skin.get("url"))
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
    }
    None
}
fn player_head_profile_uuid_from_item(item: &ItemStack) -> Option<uuid::Uuid> {
    let DataComponent::Generic {
        value: Tag::Compound(profile),
        ..
    } = item.components.get("minecraft:profile")?
    else {
        return None;
    };
    let id = compound_get(profile, "id")?;
    match id {
        Tag::String(value) => uuid::Uuid::parse_str(value).ok(),
        Tag::IntArray(values) if values.len() == 4 => {
            let mut bytes = [0_u8; 16];
            for (index, value) in values.iter().enumerate() {
                bytes[index * 4..index * 4 + 4].copy_from_slice(&value.to_be_bytes());
            }
            Some(uuid::Uuid::from_bytes(bytes))
        }
        _ => None,
    }
}
fn player_head_texture_key(url: &str) -> String {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    url.hash(&mut hasher);
    format!("player_head:{:016x}", hasher.finish())
}
fn generate_player_head_item_mesh(
    item_loc: &ResourceLocation,
    resources: &crate::resources::manager::ClientResourceManager,
    hand: crate::render::model::player::player_model::HandSide,
    display: HeldItemDisplay,
) -> (Vec<Vertex>, Vec<u32>) {
    let (display_context, right_hand_fallback) = match display {
        HeldItemDisplay::FirstPerson => (
            if hand == crate::render::model::player::player_model::HandSide::Right {
                "firstperson_righthand"
            } else {
                "firstperson_lefthand"
            },
            "firstperson_righthand",
        ),
        HeldItemDisplay::ThirdPerson => (
            if hand == crate::render::model::player::player_model::HandSide::Right {
                "thirdperson_righthand"
            } else {
                "thirdperson_lefthand"
            },
            "thirdperson_righthand",
        ),
        HeldItemDisplay::Ground => ("ground", "ground"),
        HeldItemDisplay::Fixed => ("fixed", "fixed"),
    };
    let mut special_info = None;
    if let Ok(text) = resources.read_string(
        crate::resources::manager::ClientResourceKind::ItemDefinition,
        item_loc,
    ) {
        if let Ok(json) = serde_json::from_str::<serde_json::Value>(&text) {
            if let Some(model_val) = json.get("model") {
                special_info = find_special_model(model_val, glam::Mat4::IDENTITY);
            }
        }
    }
    let base_model = special_info.as_ref().and_then(|info| {
        info.base.as_ref().and_then(|base_loc| {
            let mut actual_id = base_loc.clone();
            if !base_loc.path.contains('/') {
                actual_id = el_core::resource_location::ResourceLocation::new(
                    &base_loc.namespace,
                    &format!("block/{}", base_loc.path),
                );
            }
            BlockModel::load(resources, &actual_id).ok()
        })
    });
    let model = load_held_item_model(
        item_loc,
        resources,
        false,
        display_context,
        right_hand_fallback,
        false,
        0.0,
        el_core::item::CrossbowChargeType::None,
        25.0,
    );
    let transform_model = base_model.as_ref().or(model.as_ref());
    let transform = transform_model
        .as_ref()
        .map(|m| m.item_transform(display_context))
        .unwrap_or_default()
        .matrix(hand == crate::render::model::player::player_model::HandSide::Left);
    let extra_transform = special_info
        .as_ref()
        .map(|info| info.extra_transform)
        .unwrap_or(glam::Mat4::IDENTITY);
    let matrix = transform * extra_transform;
    let mut vertices = Vec::new();
    let mut indices = Vec::new();
    let renderer = el_inventory::special::player_head::PlayerHeadSpecialRenderer {};
    for part in el_inventory::special::SpecialModelRenderer::get_parts(&renderer, [1.0; 4]) {
        collect_special_part_vertices(
            &part,
            matrix,
            [1.0; 4],
            SpriteUvRect {
                u0: 0.0,
                v0: 0.0,
                u1: 1.0,
                v1: 1.0,
            },
            &mut vertices,
            &mut indices,
        );
    }
    (vertices, indices)
}
fn crossbow_charge_type_from_stack(stack: Option<&ItemStack>) -> el_core::item::CrossbowChargeType {
    let Some(stack) = stack else {
        return el_core::item::CrossbowChargeType::None;
    };
    if stack.item.location.path != "crossbow" {
        return el_core::item::CrossbowChargeType::None;
    }
    let Some(DataComponent::Generic {
        value: Tag::List(items),
        ..
    }) = stack.components.get("minecraft:charged_projectiles")
    else {
        return el_core::item::CrossbowChargeType::None;
    };
    if items.is_empty() {
        return el_core::item::CrossbowChargeType::None;
    }
    for item in items {
        if let Tag::Compound(fields) = item
            && let Some(Tag::String(id)) = compound_get(fields, "id")
            && (id == "minecraft:firework_rocket" || id.ends_with("firework_rocket"))
        {
            return el_core::item::CrossbowChargeType::Rocket;
        }
    }
    el_core::item::CrossbowChargeType::Arrow
}
fn crossbow_charge_duration_ticks_f32(stack: Option<&ItemStack>) -> f32 {
    let level = stack
        .map(|stack| stack_enchantment_level(stack, "minecraft:quick_charge"))
        .unwrap_or(0)
        .clamp(0, 3);
    (25 - level * 5).max(1) as f32
}
fn stack_enchantment_level(stack: &ItemStack, ench_id: &str) -> i32 {
    if let Some(DataComponent::Generic {
        value: Tag::Compound(ench_map),
        ..
    }) = stack.components.get("minecraft:enchantments")
    {
        let ench_map = match compound_get(ench_map, "levels") {
            Some(Tag::Compound(levels)) => levels,
            _ => ench_map,
        };
        if let Some(level_tag) = compound_get(ench_map, ench_id) {
            return match level_tag {
                Tag::Int(l) => *l,
                Tag::Byte(b) => *b as i32,
                Tag::Short(s) => *s as i32,
                _ => 0,
            };
        }
    }
    if let Some(DataComponent::Generic {
        value: Tag::List(ench_list),
        ..
    }) = stack.components.get("minecraft:enchantments")
    {
        for tag in ench_list {
            if let Tag::Compound(m) = tag {
                let id_match = match compound_get(m, "id") {
                    Some(Tag::String(s)) => s == ench_id || s.ends_with(ench_id),
                    _ => false,
                };
                if id_match && let Some(lvl_tag) = compound_get(m, "lvl") {
                    return match lvl_tag {
                        Tag::Int(l) => *l,
                        Tag::Byte(b) => *b as i32,
                        Tag::Short(s) => *s as i32,
                        _ => 0,
                    };
                }
            }
        }
    }
    0
}
