fn rgb_color(rgb: u32) -> [f32; 4] {
    [
        ((rgb >> 16) & 0xFF) as f32 / 255.0,
        ((rgb >> 8) & 0xFF) as f32 / 255.0,
        (rgb & 0xFF) as f32 / 255.0,
        1.0,
    ]
}
fn argb_to_color(argb: i32) -> [f32; 4] {
    let c = argb as u32;
    [
        ((c >> 16) & 0xFF) as f32 / 255.0,
        ((c >> 8) & 0xFF) as f32 / 255.0,
        (c & 0xFF) as f32 / 255.0,
        1.0,
    ]
}
fn weighted_avg_color(effects: &[(u32, u32)]) -> [f32; 4] {
    let mut r_total: u32 = 0;
    let mut g_total: u32 = 0;
    let mut b_total: u32 = 0;
    let mut weight_sum: u32 = 0;
    for &(color_rgb, weight) in effects {
        r_total += ((color_rgb >> 16) & 0xFF) * weight;
        g_total += ((color_rgb >> 8) & 0xFF) * weight;
        b_total += (color_rgb & 0xFF) * weight;
        weight_sum += weight;
    }
    if weight_sum == 0 {
        return [0.0, 0.0, 0.0, 1.0];
    }
    [
        (r_total as f32 / weight_sum as f32) / 255.0,
        (g_total as f32 / weight_sum as f32) / 255.0,
        (b_total as f32 / weight_sum as f32) / 255.0,
        1.0,
    ]
}
fn java_do_add_particle_gate(
    particle_status: i32,
    always_show: bool,
    override_limiter: bool,
    camera_pos: glam::Vec3,
    level_random: &mut impl el_math::random::RandomSource,
    pos: glam::Vec3,
) -> bool {
    let mut particle_level = particle_status;
    if always_show && particle_level == 2 && level_random.next_int_bound(10) == 0 {
        particle_level = 1;
    }
    if particle_level == 1 && level_random.next_int_bound(3) == 0 {
        particle_level = 2;
    }
    if override_limiter {
        return true;
    }
    let dx = pos.x - camera_pos.x;
    let dy = pos.y - camera_pos.y;
    let dz = pos.z - camera_pos.z;
    if dx * dx + dy * dy + dz * dz > 1024.0 {
        return false;
    }
    particle_level != 2
}
fn java_spawn_one_level_particle(
    particle_engine: &mut ParticleEngine,
    particle: &el_protocol_backend::BackendParticle,
    block_particle: Option<(&TextureAtlas, SpriteUvRect, [f32; 4])>,
    pos: glam::Vec3,
    vel: glam::Vec3,
    particle_status: i32,
    always_show: bool,
    override_limiter: bool,
    camera_pos: glam::Vec3,
    level_random: &mut impl el_math::random::RandomSource,
) {
    if java_do_add_particle_gate(
        particle_status,
        always_show,
        override_limiter,
        camera_pos,
        level_random,
        pos,
    ) {
        particle_engine.spawn_network_particle(particle, pos, vel, block_particle);
    }
}
fn block_break_particle_uv_rect(
    block_state: &BlockState,
    model_cache: &HashMap<String, BakedModel>,
) -> Option<SpriteUvRect> {
    let model_key = ChunkMesher::block_state_model_key(block_state);
    let model = model_cache
        .get(&model_key)
        .or_else(|| model_cache.get(&block_state.block.to_string()))
        .or_else(|| model_cache.get(&block_state.block.path))?;
    if let Some(sprite) = model.particle_sprite() {
        return Some(sprite);
    }
    let quads = model.quads_for_seed(0);
    let quad = quads.first()?;
    let mut u0 = f32::INFINITY;
    let mut v0 = f32::INFINITY;
    let mut u1 = f32::NEG_INFINITY;
    let mut v1 = f32::NEG_INFINITY;
    for [u, v] in quad.vertex_uvs {
        u0 = u0.min(u);
        v0 = v0.min(v);
        u1 = u1.max(u);
        v1 = v1.max(v);
    }
    if !(u0.is_finite() && v0.is_finite() && u1.is_finite() && v1.is_finite() && u1 > u0 && v1 > v0)
    {
        return None;
    }
    Some(SpriteUvRect { u0, v0, u1, v1 })
}
